{"command":"cat > src/common.rs <<'RS'
use std::collections::{BTreeSet, HashSet};
use std::fs;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ByteFormat {
    Metric,
    Binary,
    Bytes,
    GB,
    GiB,
    MB,
    MiB,
}

impl ByteFormat {
    pub fn from_str(s: &str) -> Option<Self> {
        match s.to_ascii_lowercase().as_str() {
            "metric" => Some(Self::Metric),
            "binary" => Some(Self::Binary),
            "bytes" => Some(Self::Bytes),
            "gb" => Some(Self::GB),
            "gib" => Some(Self::GiB),
            "mb" => Some(Self::MB),
            "mib" => Some(Self::MiB),
            _ => None,
        }
    }
    pub fn debug_name(&self) -> &'static str {
        match self {
            Self::Metric => "Metric",
            Self::Binary => "Binary",
            Self::Bytes => "Bytes",
            Self::GB => "GB",
            Self::GiB => "GiB",
            Self::MB => "MB",
            Self::MiB => "MiB",
        }
    }
}

pub fn format_size(size: u64, format: ByteFormat) -> String {
    match format {
        ByteFormat::Bytes => format!("{:>10} b", size),
        ByteFormat::GB => {
            let v = size as f64 / 1_000_000_000.0;
            format!("{:>7} GB", format!("{:.2}", v))
        }
        ByteFormat::GiB => {
            let v = size as f64 / 1_073_741_824.0;
            format!("{:>6} GiB", format!("{:.2}", v))
        }
        ByteFormat::MB => {
            let v = size as f64 / 1_000_000.0;
            format!("{:>9} MB", format!("{:.2}", v))
        }
        ByteFormat::MiB => {
            let v = size as f64 / 1_048_576.0;
            format!("{:>8} MiB", format!("{:.2}", v))
        }
        ByteFormat::Metric => {
            const UNITS: &[&str] = &["B", "KB", "MB", "GB", "TB", "PB", "EB"];
            let mut v = size as f64;
            let mut idx = 0usize;
            while v > 1000.0 && idx + 1 < UNITS.len() {
                v /= 1000.0;
                idx += 1;
            }
            let num = if idx == 0 {
                format!("{}", size)
            } else {
                format!("{:.2}", v)
            };
            format!("{:>7} {:>2}", num, UNITS[idx])
        }
        ByteFormat::Binary => {
            const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
            let mut v = size as f64;
            let mut idx = 0usize;
            while v > 1024.0 && idx + 1 < UNITS.len() {
                v /= 1024.0;
                idx += 1;
            }
            let num = if idx == 0 {
                format!("{}", size)
            } else {
                format!("{:.2}", v)
            };
            format!("{:>7} {:>3}", num, UNITS[idx])
        }
    }
}

#[derive(Clone, Debug)]
pub struct WalkOptions {
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_filesystem: bool,
    pub ignore_dirs: Vec<PathBuf>,
}

impl WalkOptions {
    pub fn canonical_ignore_set(&self) -> BTreeSet<PathBuf> {
        self.ignore_dirs
            .iter()
            .map(|p| p.canonicalize().unwrap_or_else(|_| p.clone()))
            .collect()
    }
}

#[derive(Clone, Debug, Default)]
pub struct Statistics {
    pub entries_traversed: u64,
    pub smallest_file_in_bytes: u64,
    pub largest_file_in_bytes: u64,
}

impl Statistics {
    pub fn add(&mut self, size: u64) {
        if self.entries_traversed == 0 {
            self.smallest_file_in_bytes = size;
            self.largest_file_in_bytes = size;
        } else {
            self.smallest_file_in_bytes = self.smallest_file_in_bytes.min(size);
            self.largest_file_in_bytes = self.largest_file_in_bytes.max(size);
        }
        self.entries_traversed += 1;
    }
    pub fn merge(&mut self, other: &Statistics) {
        // Not used with a shared statistics object; kept for completeness.
        for _ in 0..other.entries_traversed {
            let _ = other;
            break;
        }
        if other.entries_traversed > 0 {
            if self.entries_traversed == 0 {
                self.smallest_file_in_bytes = other.smallest_file_in_bytes;
                self.largest_file_in_bytes = other.largest_file_in_bytes;
            } else {
                self.smallest_file_in_bytes =
                    self.smallest_file_in_bytes.min(other.smallest_file_in_bytes);
                self.largest_file_in_bytes =
                    self.largest_file_in_bytes.max(other.largest_file_in_bytes);
            }
            self.entries_traversed += other.entries_traversed;
        }
    }
}

pub fn entry_size(metadata: &fs::Metadata, apparent_size: bool) -> u64 {
    if apparent_size {
        metadata.len()
    } else {
        metadata.blocks() * 512
    }
}

#[derive(Clone)]
pub struct EntryInfo {
    pub size: u64,
    pub metadata: fs::Metadata,
    pub is_dir_follow: bool,
    pub is_real_dir: bool,
