            format!("{:>7} {:>2}", num, UNITS[idx])
        }
        ByteFormat::Binary => {
            const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
            let mut v = size as f64;
            let mut idx = 0usize;
            while v > 1024.0 && idx + 1 < UNITS.len() {
                v /= 1024.0;
                idx += 1;
            }
            let num = if idx == 0 {
                format!("{}", size)
            } else {
                format!("{:.2}", v)
            };
            format!("{:>7} {:>3}", num, UNITS[idx])
        }
    }
}

#[derive(Clone, Debug)]
pub struct WalkOptions {
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_filesystem: bool,
    pub ignore_dirs: Vec<PathBuf>,
}

impl WalkOptions {
    pub fn canonical_ignore_set(&self) -> BTreeSet<PathBuf> {
        self.ignore_dirs
            .iter()
            .map(|p| p.canonicalize().unwrap_or_else(|_| p.clone()))
            .collect()
    }
}

#[derive(Clone, Debug, Default)]
pub struct Statistics {
    pub entries_traversed: u64,
    pub smallest_file_in_bytes: u64,
    pub largest_file_in_bytes: u64,
}

impl Statistics {
    pub fn add(&mut self, size: u64) {
        if self.entries_traversed == 0 {
            self.smallest_file_in_bytes = size;
            self.largest_file_in_bytes = size;
        } else {
            self.smallest_file_in_bytes = self.smallest_file_in_bytes.min(size);
            self.largest_file_in_bytes = self.largest_file_in_bytes.max(size);
        }
        self.entries_traversed += 1;
    }
    pub fn merge(&mut self, other: &Statistics) {
        // Not used with a shared statistics object; kept for completeness.
        for _ in 0..other.entries_traversed {
            let _ = other;
            break;
        }
        if other.entries_traversed > 0 {
            if self.entries_traversed == 0 {
                self.smallest_file_in_bytes = other.smallest_file_in_bytes;
                self.largest_file_in_bytes = other.largest_file_in_bytes;
            } else {
                self.smallest_file_in_bytes =
                    self.smallest_file_in_bytes.min(other.smallest_file_in_bytes);
                self.largest_file_in_bytes =
                    self.largest_file_in_bytes.max(other.largest_file_in_bytes);
            }
            self.entries_traversed += other.entries_traversed;
        }
    }
}

pub fn entry_size(metadata: &fs::Metadata, apparent_size: bool) -> u64 {
    if apparent_size {
        metadata.len()
    } else {
        metadata.blocks() * 512
    }
}

#[derive(Clone)]
pub struct EntryInfo {
    pub size: u64,
    pub metadata: fs::Metadata,
    pub is_dir_follow: bool,
    pub is_real_dir: bool,
    pub is_symlink: bool,
}

impl EntryInfo {
    pub fn is_dir(&self) -> bool {
        self.is_real_dir
    }
}

/// Shared state across a whole traversal run (all roots).
pub struct TraversalState {
    pub seen_inodes: HashSet<(u64, u64)>,
    pub statistics: Statistics,
    pub ignore_set: BTreeSet<PathBuf>,
}

impl TraversalState {
    pub fn new(ignore_set: BTreeSet<PathBuf>) -> Self {
        Self {
            seen_inodes: HashSet::new(),
            statistics: Statistics::default(),
            ignore_set,
        }
    }
    fn effective_size(
        &mut self,
        metadata: &fs::Metadata,
        apparent_size: bool,
        count_hard_links: bool,
    ) -> u64 {
        let size = entry_size(metadata, apparent_size);
        if count_hard_links {
            return size;
        }
        if metadata.nlink() > 1 {
            let key = (metadata.dev(), metadata.ino());
            if !self.seen_inodes.insert(key) {
                return 0;
            }
        }
        size
    }
}

/// Information gathered for one entry before recursion.
fn info_explicit_root(path: &Path) -> Option<(EntryInfo, fs::Metadata)> {
    // Following metadata determines root existence/type.
    let followed = fs::metadata(path).ok()?;
    let lstat = fs::symlink_metadata(path).ok()?;
    let is_real_dir = lstat.file_type().is_dir();
    let info = EntryInfo {
        size: 0,
        is_dir_follow: followed.is_dir(),
        is_real_dir,
        is_symlink: lstat.file_type().is_symlink(),
        metadata: lstat,
    };
    Some((info, followed))
}

fn info_nested(path: &Path) -> Option<EntryInfo> {
    let lstat = fs::symlink_metadata(path).ok()?;
    let is_real_dir = lstat.file_type().is_dir();
    Some(EntryInfo {
        size: 0,
        is_dir_follow: is_real_dir,
        is_real_dir,
        is_symlink: lstat.file_type().is_symlink(),
        metadata: lstat,
    })
}

#[derive(Default, Clone, Copy)]
pub struct RootOutcome {
    pub size: u64,
    pub errors: u64,
}

/// Recursive walker for aggregate mode. Returns total size for `path`.
///
/// * `is_root` – `path` is an explicit traversal root (follows symlinks).
/// * `root_device` – device of the top-level root, for stay-on-filesystem.
pub fn walk_aggregate(
    path: &Path,
    is_root: bool,
    root_device: Option<u64>,
    opts: &WalkOptions,
    state: &mut TraversalState,
    errors: &mut u64,
) -> u64 {
    let (mut info, followed_dev) = if is_root {
        match info_explicit_root(path) {
            Some((info, followed)) => {
                let dev = followed.dev();
                (info, Some(dev))
            }
            None => {
                *errors += 1;
                return 0;
            }
        }
    } else {
        match info_nested(path) {
            Some(info) => (info, None),
            None => {
                *errors += 1;
                return 0;
            }
        }
    };
    let root_device = if is_root {
        followed_dev
    } else {
        root_device
    };
    let size = state.effective_size(&info.metadata, opts.apparent_size, opts.count_hard_links);
    info.size = size;
    state.statistics.add(size);
    let mut total = size;

    let descend = if is_root { info.is_dir_follow } else { info.is_real_dir };
    if !descend {
        return total;
    }
    // Pruning checks (not applied to a directory that is an expansion origin,
    // which is handled because expansion roots *are* the children; an explicit
    // aggregate root, however, is pruned when ignored / off-filesystem in the
    // multi-root walk sense. For a root the filesystem check is vacuous.)
    if !is_root || true {
        // ignore check: applies to nested dirs and to explicit roots alike.
        // (The single-input directory case never reaches here with the input
        // itself, because it is expanded before traversal.)
        if is_real_dir_ignored(path, state) {
            return total;
        }
        if opts.stay_on_filesystem && !is_root {
            if let Some(rd) = root_device {
                if info.metadata.dev() != rd {
                    return total;
                }
            }
        }
        // A root which is a symlink to a directory on another filesystem:
        // treat target device as root device (already set from followed meta).
    }
    if let Ok(read_dir) = fs::read_dir(path) {
        for entry in read_dir {
            if let Ok(entry) = entry {
                let child = entry.path();
                total += walk_aggregate(&child, false, root_device, opts, state, errors);
            }
        }
    }
    total
}

fn is_real_dir_ignored(path: &Path, state: &TraversalState) -> bool {
    if state.ignore_set.is_empty() {
        return false;
    }
    // Only directories can be in the ignore set in practice; canonicalising a
    // non-existent or non-directory path simply will not match for files
    // because we only call this for directories.
    match path.canonicalize() {
        Ok(canon) => state.ignore_set.contains(&canon),
        Err(_) => state.ignore_set.contains(path),
    }
}

pub fn should_descend_dir(
    path: &Path,
    info: &EntryInfo,
    root_device: Option<u64>,
    opts: &WalkOptions,
    state: &TraversalState,
) -> bool {
    if is_real_dir_ignored(path, state) {
        return false;
    }
    if opts.stay_on_filesystem {
        if let Some(rd) = root_device {
            if info.metadata.dev() != rd {
                return false;
            }
        }
    }
    true
}

pub fn get_info_root(path: &Path) -> Option<(EntryInfo, u64)> {
    let (info, followed) = info_explicit_root(path)?;
    Some((info, followed.dev()))
}

pub fn get_info_nested(path: &Path) -> Option<EntryInfo> {
    info_nested(path)
}

pub fn effective_size_pub(
    state: &mut TraversalState,
    metadata: &fs::Metadata,
    apparent_size: bool,
    count_hard_links: bool,
) -> u64 {
    state.effective_size(metadata, apparent_size, count_hard_links)
}

pub fn mtime_of(metadata: &fs::Metadata) -> SystemTime {
    metadata.modified().unwrap_or(SystemTime::UNIX_EPOCH)
}

/// A discovered root for aggregate: filesystem path plus display path.
#[derive(Clone, Debug)]
pub struct RootPath {
    pub fs_path: PathBuf,
    pub display: PathBuf,
}

/// Determine aggregate roots, following the observed expansion rules.
pub fn aggregate_roots(
    inputs: &[PathBuf],
    opts: &WalkOptions,
) -> anyhow::Result<Vec<RootPath>> {
    if inputs.len() == 1 && inputs[0].is_dir() {
        let dir = &inputs[0];
        let roots = expand_dir(dir, opts)?;
        Ok(roots)
    } else if inputs.is_empty() {
        let cwd = PathBuf::from(".");
        let roots = expand_dir(&cwd, opts)?;
        Ok(roots)
    } else {
        Ok(inputs
            .iter()
            .map(|p| RootPath {
                fs_path: p.clone(),
                display: p.clone(),
            })
            .collect())
    }
}

pub fn expand_dir(dir: &Path, opts: &WalkOptions) -> anyhow::Result<Vec<RootPath>> {
    let parent_dev = if opts.stay_on_filesystem {
        fs::metadata(dir).map(|m| m.dev()).ok()
    } else {
        None
    };
    let mut roots = Vec::new();
    let read_dir = fs::read_dir(dir)?;
    for entry in read_dir {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let file_type = match entry.file_type() {
            Ok(ft) => ft,
            Err(_) => continue,
        };
        if file_type.is_symlink() {
            continue;
        }
        let path = entry.path();
        if opts.stay_on_filesystem {
            if let Some(pd) = parent_dev {
                if let Ok(md) = fs::symlink_metadata(&path) {
                    // Only directory entries are mount points; follow the
                    // observed rule that such entries are filtered out.
                    if md.dev() != pd {
                        continue;
                    }
                }
            }
        }
        let display = PathBuf::from(entry.file_name());
        roots.push(RootPath {
            fs_path: path,
            display,
        });
    }
    roots.sort_by(|a, b| a.display.cmp(&b.display));
    Ok(roots)
}
