use crate::common::*;
use std::io::Write;
use std::path::PathBuf;

pub struct AggregateOptions {
    pub statistics: bool,
    pub no_sort: bool,
    pub no_total: bool,
}

pub fn run(
    inputs: &[PathBuf],
    agg: &AggregateOptions,
    walk_opts: &WalkOptions,
    format: ByteFormat,
) -> anyhow::Result<i32> {
    let roots = aggregate_roots(inputs, walk_opts)?;
    let ignore_set = walk_opts.canonical_ignore_set();
    let mut state = TraversalState::new(ignore_set);
    let mut results: Vec<(u64, PathBuf, PathBuf, u64)> = Vec::new(); // size, fs_path, display, errors
    for root in &roots {
        let mut errors: u64 = 0;
        let size = walk_aggregate(
            &root.fs_path,
            true,
            None,
            walk_opts,
            &mut state,
            &mut errors,
        );
        results.push((size, root.fs_path.clone(), root.display.clone(), errors));
    }
    if !agg.no_sort {
        // Stable sort by size ascending.
        results.sort_by_key(|r| r.0);
    }
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let mut total_size: u64 = 0;
    let mut total_errors: u64 = 0;
    for (size, fs_path, display, errors) in &results {
        total_size += size;
        total_errors += errors;
        write_result(&mut out, *size, fs_path, display, *errors, format)?;
    }
    if results.len() > 1 && !agg.no_total {
        let mut line = format!(
            "\x1b[32m{}\x1b[39m total",
            format_size(total_size, format)
        );
        if total_errors > 0 {
            line.push_str(&format!(
                "  <{} IO Error{}>",
                total_errors,
                if total_errors == 1 { "" } else { "s" }
            ));
        }
        writeln!(out, "{}", line)?;
    }
    if agg.statistics {
        eprintln!(
            "Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}",
            state.statistics.entries_traversed,
            state.statistics.smallest_file_in_bytes,
            state.statistics.largest_file_in_bytes
        );
    }
    Ok(if total_errors > 0 { 1 } else { 0 })
}

fn write_result<W: Write>(
    out: &mut W,
    size: u64,
    fs_path: &std::path::Path,
    display: &PathBuf,
    errors: u64,
    format: ByteFormat,
) -> anyhow::Result<()> {
    let size_str = format_size(size, format);
    let display_str = display.to_string_lossy();
    let path_part = if fs_path.is_file() {
        display_str.into_owned()
    } else {
        format!("\x1b[36m{}\x1b[39m", display_str)
    };
    let mut line = format!("\x1b[32m{}\x1b[39m {}", size_str, path_part);
    if errors > 0 {
        line.push_str(&format!(
            "  <{} IO Error{}>",
            errors,
            if errors == 1 { "" } else { "s" }
        ));
    }
    writeln!(out, "{}", line)?;
    Ok(())
}
