use crate::common::ByteFormat;
use clap::{Arg, ArgAction, Command};
use std::path::PathBuf;

#[derive(Debug, Clone, PartialEq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    Powershell,
    Zsh,
}
impl Shell {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "bash" => Some(Self::Bash),
            "elvish" => Some(Self::Elvish),
            "fish" => Some(Self::Fish),
            "powershell" => Some(Self::Powershell),
            "zsh" => Some(Self::Zsh),
            _ => None,
        }
    }
    pub fn debug_name(&self) -> &'static str {
        match self {
            Self::Bash => "Bash",
            Self::Elvish => "Elvish",
            Self::Fish => "Fish",
            Self::Powershell => "Powershell",
            Self::Zsh => "Zsh",
        }
    }
    pub fn name(&self) -> &'static str {
        match self {
            Self::Bash => "bash",
            Self::Elvish => "elvish",
            Self::Fish => "fish",
            Self::Powershell => "powershell",
            Self::Zsh => "zsh",
        }
    }
}

#[derive(Debug, Clone)]
pub enum CommandKind {
    Interactive { no_entry_check: bool, input: Vec<PathBuf> },
    Aggregate { statistics: bool, no_sort: bool, no_total: bool, input: Vec<PathBuf> },
    Completions { shell: Shell },
}

#[derive(Debug, Clone)]
pub struct Args {
    pub command: Option<CommandKind>,
    pub threads: usize,
    pub format: ByteFormat,
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_filesystem: bool,
    pub ignore_dirs: Vec<PathBuf>,
    pub input: Vec<PathBuf>,
    pub log_file: Option<PathBuf>,
}

const INPUT_HELP: &str =
    "One or more input files or directories. If unset, we will use all entries in the current working directory";

pub fn build_cli() -> Command {
    let input_arg = Arg::new("input")
        .help(INPUT_HELP)
        .num_args(0..)
        .action(ArgAction::Append)
        .value_parser(clap::value_parser!(PathBuf));
    Command::new("dua")
        .version("2.32.2")
        .about("A tool to learn about disk usage, fast!")
        .override_usage("dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...")
        .args_conflicts_with_subcommands(true)
        .arg(
            Arg::new("threads")
                .short('t')
                .long("threads")
                .value_name("THREADS")
                .help("The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread")
                .default_value("0")
                .value_parser(clap::value_parser!(usize)),
        )
        .arg(
            Arg::new("format")
                .short('f')
                .long("format")
                .value_name("FORMAT")
                .help("The format with which to print byte counts")
                .default_value("binary")
                .ignore_case(true)
                .value_parser(["metric", "binary", "bytes", "gb", "gib", "mb", "mib"]),
        )
        .arg(
            Arg::new("apparent_size")
                .short('A')
                .long("apparent-size")
                .help("Display apparent size instead of disk usage")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("count_hard_links")
                .short('l')
                .long("count-hard-links")
                .help("Count hard-linked files each time they are seen")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("stay_on_filesystem")
                .short('x')
                .long("stay-on-filesystem")
                .help("If set, we will not cross filesystems or traverse mount points")
                .action(ArgAction::SetTrue),
