use crate::common::ByteFormat;
use clap::{Arg, ArgAction, Command};
use std::path::PathBuf;

#[derive(Debug, Clone, PartialEq)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    Powershell,
    Zsh,
}
impl Shell {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "bash" => Some(Self::Bash),
            "elvish" => Some(Self::Elvish),
            "fish" => Some(Self::Fish),
            "powershell" => Some(Self::Powershell),
            "zsh" => Some(Self::Zsh),
            _ => None,
        }
    }
    pub fn debug_name(&self) -> &'static str {
        match self {
            Self::Bash => "Bash",
            Self::Elvish => "Elvish",
            Self::Fish => "Fish",
            Self::Powershell => "Powershell",
            Self::Zsh => "Zsh",
        }
    }
    pub fn name(&self) -> &'static str {
        match self {
            Self::Bash => "bash",
            Self::Elvish => "elvish",
            Self::Fish => "fish",
            Self::Powershell => "powershell",
            Self::Zsh => "zsh",
        }
    }
}

#[derive(Debug, Clone)]
pub enum CommandKind {
    Interactive { no_entry_check: bool, input: Vec<PathBuf> },
    Aggregate { statistics: bool, no_sort: bool, no_total: bool, input: Vec<PathBuf> },
    Completions { shell: Shell },
}

#[derive(Debug, Clone)]
pub struct Args {
    pub command: Option<CommandKind>,
    pub threads: usize,
    pub format: ByteFormat,
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_filesystem: bool,
    pub ignore_dirs: Vec<PathBuf>,
    pub input: Vec<PathBuf>,
    pub log_file: Option<PathBuf>,
}

const INPUT_HELP: &str =
    "One or more input files or directories. If unset, we will use all entries in the current working directory";

pub fn build_cli() -> Command {
    let input_arg = Arg::new("input")
        .help(INPUT_HELP)
        .num_args(0..)
        .action(ArgAction::Append)
        .value_parser(clap::value_parser!(PathBuf));
    Command::new("dua")
        .version("2.32.2")
        .about("A tool to learn about disk usage, fast!")
        .override_usage("dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...")
        .args_conflicts_with_subcommands(true)
        .arg(
            Arg::new("threads")
                .short('t')
                .long("threads")
                .value_name("THREADS")
                .help("The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread")
                .default_value("0")
                .value_parser(clap::value_parser!(usize)),
        )
        .arg(
            Arg::new("format")
                .short('f')
                .long("format")
                .value_name("FORMAT")
                .help("The format with which to print byte counts")
                .default_value("binary")
                .ignore_case(true)
                .value_parser(["metric", "binary", "bytes", "gb", "gib", "mb", "mib"]),
        )
        .arg(
            Arg::new("apparent_size")
                .short('A')
                .long("apparent-size")
                .help("Display apparent size instead of disk usage")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("count_hard_links")
                .short('l')
                .long("count-hard-links")
                .help("Count hard-linked files each time they are seen")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("stay_on_filesystem")
                .short('x')
                .long("stay-on-filesystem")
                .help("If set, we will not cross filesystems or traverse mount points")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("ignore_dirs")
                .short('i')
                .long("ignore-dirs")
                .value_name("IGNORE_DIRS")
                .help("One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path.")
                .long_help("One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path.\n\nHence, they will only be ignored if they are eventually reached as part of the traversal.")
                .default_values(["/proc", "/dev", "/sys", "/run"])
                .action(ArgAction::Append)
                .value_parser(clap::value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("log_file")
                .long("log-file")
                .value_name("LOG_FILE")
                .help("Write a log file with debug information, including panics")
                .value_parser(clap::value_parser!(PathBuf)),
        )
        .arg(input_arg.clone())
        .subcommand(
            Command::new("interactive")
                .alias("i")
                .about("Launch the terminal user interface")
                .arg(
                    Arg::new("no_entry_check")
                        .short('e')
                        .long("no-entry-check")
                        .help("Do not check entries for presence when listing a directory to avoid slugging performance on slow filesystems")
                        .action(ArgAction::SetTrue),
                )
                .arg(input_arg.clone()),
        )
        .subcommand(
            Command::new("aggregate")
                .alias("a")
                .about("Aggregate the consumed space of one or more directories or files")
                .arg(
                    Arg::new("statistics")
                        .long("stats")
                        .help("If set, print additional statistics about the file traversal to stderr")
                        .action(ArgAction::SetTrue),
                )
                .arg(
                    Arg::new("no_sort")
                        .long("no-sort")
                        .help("If set, paths will be printed in their order of occurrence on the command-line. Otherwise they are sorted by their size in bytes, ascending")
                        .action(ArgAction::SetTrue),
                )
                .arg(
                    Arg::new("no_total")
                        .long("no-total")
                        .help("If set, no total column will be computed for multiple inputs")
                        .action(ArgAction::SetTrue),
                )
                .arg(input_arg.clone()),
        )
        .subcommand(
            Command::new("completions")
                .about("Generate shell completions")
                .arg(
                    Arg::new("shell")
                        .help("The shell to generate a completions-script for")
                        .required(true)
                        .value_parser(["bash", "elvish", "fish", "powershell", "zsh"]),
                ),
        )
}

pub fn parse() -> Args {
    let matches = build_cli().get_matches();
    parse_from_matches(&matches)
}

pub fn parse_from_matches(matches: &clap::ArgMatches) -> Args {
    let threads = *matches.get_one::<usize>("threads").unwrap_or(&0);
    let format_str = matches
        .get_one::<String>("format")
        .map(|s| s.as_str())
        .unwrap_or("binary");
    let format = ByteFormat::from_str(format_str).unwrap_or(ByteFormat::Binary);
    let ignore_dirs: Vec<PathBuf> = matches
        .get_many::<PathBuf>("ignore_dirs")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let log_file = matches.get_one::<PathBuf>("log_file").cloned();
    let mut input: Vec<PathBuf> = matches
        .get_many::<PathBuf>("input")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let command = match matches.subcommand() {
        Some(("interactive", sub)) => Some(CommandKind::Interactive {
            no_entry_check: sub.get_flag("no_entry_check"),
            input: sub
                .get_many::<PathBuf>("input")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
        }),
        Some(("aggregate", sub)) => Some(CommandKind::Aggregate {
            statistics: sub.get_flag("statistics"),
            no_sort: sub.get_flag("no_sort"),
            no_total: sub.get_flag("no_total"),
            input: sub
                .get_many::<PathBuf>("input")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
        }),
        Some(("completions", sub)) => {
            let shell_str = sub.get_one::<String>("shell").unwrap();
            Some(CommandKind::Completions {
                shell: Shell::from_str(shell_str).unwrap_or(Shell::Bash),
            })
        }
        _ => None,
    };
    if command.is_some() {
        // Root-level input is unused when a subcommand is present, mirroring
        // the original debug output where `input` stays empty in that case.
        input.clear();
    }
    Args {
        command,
        threads,
        format,
        apparent_size: matches.get_flag("apparent_size"),
        count_hard_links: matches.get_flag("count_hard_links"),
        stay_on_filesystem: matches.get_flag("stay_on_filesystem"),
        ignore_dirs,
        input,
        log_file,
    }
}

/// Render the pretty-Debug representation used in the log file.
pub fn debug_args(args: &Args) -> String {
    let mut s = String::new();
    s.push_str("Args {\n");
    match &args.command {
        Some(CommandKind::Aggregate {
            statistics,
            no_sort,
            no_total,
            input,
        }) => {
            s.push_str("    command: Some(\n");
            s.push_str("        Aggregate {\n");
            s.push_str(&format!("            statistics: {},\n", statistics));
            s.push_str(&format!("            no_sort: {},\n", no_sort));
            s.push_str(&format!("            no_total: {},\n", no_total));
            s.push_str("            input: ");
            s.push_str(&debug_path_list(input, 12));
            s.push_str(",\n");
            s.push_str("        },\n");
            s.push_str("    ),\n");
        }
        Some(CommandKind::Interactive {
            no_entry_check,
            input,
        }) => {
            s.push_str("    command: Some(\n");
            s.push_str("        Interactive {\n");
            s.push_str(&format!("            no_entry_check: {},\n", no_entry_check));
            s.push_str("            input: ");
            s.push_str(&debug_path_list(input, 12));
            s.push_str(",\n");
            s.push_str("        },\n");
            s.push_str("    ),\n");
        }
        Some(CommandKind::Completions { shell }) => {
            s.push_str("    command: Some(\n");
            s.push_str("        Completions {\n");
            s.push_str(&format!("            shell: {},\n", shell.debug_name()));
            s.push_str("        },\n");
            s.push_str("    ),\n");
        }
        None => {
            s.push_str("    command: None,\n");
        }
    }
    s.push_str(&format!("    threads: {},\n", args.threads));
    s.push_str(&format!("    format: {},\n", args.format.debug_name()));
    s.push_str(&format!("    apparent_size: {},\n", args.apparent_size));
    s.push_str(&format!(
        "    count_hard_links: {},\n",
        args.count_hard_links
    ));
    s.push_str(&format!(
        "    stay_on_filesystem: {},\n",
        args.stay_on_filesystem
    ));
    s.push_str("    ignore_dirs: ");
    s.push_str(&debug_path_list(&args.ignore_dirs, 4));
    s.push_str(",\n");
    s.push_str("    input: ");
    s.push_str(&debug_path_list(&args.input, 4));
    s.push_str(",\n");
    match &args.log_file {
        Some(p) => {
            s.push_str("    log_file: Some(\n");
            s.push_str(&format!("        {:?},\n", p));
            s.push_str("    ),\n");
        }
        None => s.push_str("    log_file: None,\n"),
    }
    s.push('}');
    s
}

fn debug_path_list(paths: &[PathBuf], indent: usize) -> String {
    if paths.is_empty() {
        return "[]".to_string();
    }
    let pad = " ".repeat(indent);
    let inner_pad = " ".repeat(indent + 4);
    let mut s = String::from("[\n");
    for p in paths {
        s.push_str(&format!("{}{:?},\n", inner_pad, p));
    }
    s.push_str(&pad);
    s.push(']');
    s
}
