            Command::new("interactive")
                .alias("i")
                .about("Launch the terminal user interface")
                .arg(
                    Arg::new("no_entry_check")
                        .short('e')
                        .long("no-entry-check")
                        .help("Do not check entries for presence when listing a directory to avoid slugging performance on slow filesystems")
                        .action(ArgAction::SetTrue),
                )
                .arg(input_arg.clone()),
        )
        .subcommand(
            Command::new("aggregate")
                .alias("a")
                .about("Aggregate the consumed space of one or more directories or files")
                .arg(
                    Arg::new("statistics")
                        .long("stats")
                        .help("If set, print additional statistics about the file traversal to stderr")
                        .action(ArgAction::SetTrue),
                )
                .arg(
                    Arg::new("no_sort")
                        .long("no-sort")
                        .help("If set, paths will be printed in their order of occurrence on the command-line. Otherwise they are sorted by their size in bytes, ascending")
                        .action(ArgAction::SetTrue),
                )
                .arg(
                    Arg::new("no_total")
                        .long("no-total")
                        .help("If set, no total column will be computed for multiple inputs")
                        .action(ArgAction::SetTrue),
                )
                .arg(input_arg.clone()),
        )
        .subcommand(
            Command::new("completions")
                .about("Generate shell completions")
                .arg(
                    Arg::new("shell")
                        .help("The shell to generate a completions-script for")
                        .required(true)
                        .value_parser(["bash", "elvish", "fish", "powershell", "zsh"]),
                ),
        )
}

pub fn parse() -> Args {
    let matches = build_cli().get_matches();
    parse_from_matches(&matches)
}

pub fn parse_from_matches(matches: &clap::ArgMatches) -> Args {
    let threads = *matches.get_one::<usize>("threads").unwrap_or(&0);
    let format_str = matches
        .get_one::<String>("format")
        .map(|s| s.as_str())
        .unwrap_or("binary");
    let format = ByteFormat::from_str(format_str).unwrap_or(ByteFormat::Binary);
    let ignore_dirs: Vec<PathBuf> = matches
        .get_many::<PathBuf>("ignore_dirs")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let log_file = matches.get_one::<PathBuf>("log_file").cloned();
    let mut input: Vec<PathBuf> = matches
        .get_many::<PathBuf>("input")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let command = match matches.subcommand() {
        Some(("interactive", sub)) => Some(CommandKind::Interactive {
            no_entry_check: sub.get_flag("no_entry_check"),
            input: sub
                .get_many::<PathBuf>("input")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
        }),
        Some(("aggregate", sub)) => Some(CommandKind::Aggregate {
            statistics: sub.get_flag("statistics"),
            no_sort: sub.get_flag("no_sort"),
            no_total: sub.get_flag("no_total"),
            input: sub
                .get_many::<PathBuf>("input")
                .map(|v| v.cloned().collect())
                .unwrap_or_default(),
        }),
        Some(("completions", sub)) => {
            let shell_str = sub.get_one::<String>("shell").unwrap();
            Some(CommandKind::Completions {
                shell: Shell::from_str(shell_str).unwrap_or(Shell::Bash),
            })
        }
        _ => None,
    };
    if command.is_some() {
        // Root-level input is unused when a subcommand is present, mirroring
        // the original debug output where `input` stays empty in that case.
        input.clear();
    }
    Args {
        command,
        threads,
        format,
        apparent_size: matches.get_flag("apparent_size"),
        count_hard_links: matches.get_flag("count_hard_links"),
        stay_on_filesystem: matches.get_flag("stay_on_filesystem"),
        ignore_dirs,
        input,
        log_file,
    }
}

/// Render the pretty-Debug representation used in the log file.
pub fn debug_args(args: &Args) -> String {
    let mut s = String::new();
    s.push_str("Args {\n");
    match &args.command {
        Some(CommandKind::Aggregate {
            statistics,
            no_sort,
            no_total,
            input,
        }) => {
            s.push_str("    command: Some(\n");
            s.push_str("        Aggregate {\n");
            s.push_str(&format!("            statistics: {},\n", statistics));
            s.push_str(&format!("            no_sort: {},\n", no_sort));
            s.push_str(&format!("            no_total: {},\n", no_total));
            s.push_str("            input: ");
            s.push_str(&debug_path_list(input, 12));
            s.push_str(",\n");
            s.push_str("        },\n");
            s.push_str("    ),\n");
        }
        Some(CommandKind::Interactive {
            no_entry_check,
            input,
        }) => {
            s.push_str("    command: Some(\n");
            s.push_str("        Interactive {\n");
            s.push_str(&format!("            no_entry_check: {},\n", no_entry_check));
            s.push_str("            input: ");
            s.push_str(&debug_path_list(input, 12));
            s.push_str(",\n");
            s.push_str("        },\n");
            s.push_str("    ),\n");
        }
        Some(CommandKind::Completions { shell }) => {
            s.push_str("    command: Some(\n");
            s.push_str("        Completions {\n");
            s.push_str(&format!("            shell: {},\n", shell.debug_name()));
            s.push_str("        },\n");
            s.push_str("    ),\n");
        }
        None => {
            s.push_str("    command: None,\n");
        }
    }
    s.push_str(&format!("    threads: {},\n", args.threads));
    s.push_str(&format!("    format: {},\n", args.format.debug_name()));
    s.push_str(&format!("    apparent_size: {},\n", args.apparent_size));
    s.push_str(&format!(
        "    count_hard_links: {},\n",
        args.count_hard_links
    ));
    s.push_str(&format!(
        "    stay_on_filesystem: {},\n",
        args.stay_on_filesystem
    ));
    s.push_str("    ignore_dirs: ");
    s.push_str(&debug_path_list(&args.ignore_dirs, 4));
    s.push_str(",\n");
    s.push_str("    input: ");
    s.push_str(&debug_path_list(&args.input, 4));
    s.push_str(",\n");
    match &args.log_file {
        Some(p) => {
            s.push_str("    log_file: Some(\n");
            s.push_str(&format!("        {:?},\n", p));
            s.push_str("    ),\n");
        }
        None => s.push_str("    log_file: None,\n"),
    }
    s.push('}');
    s
}

fn debug_path_list(paths: &[PathBuf], indent: usize) -> String {
    if paths.is_empty() {
        return "[]".to_string();
    }
    let pad = " ".repeat(indent);
    let inner_pad = " ".repeat(indent + 4);
    let mut s = String::from("[\n");
    for p in paths {
        s.push_str(&format!("{}{:?},\n", inner_pad, p));
    }
    s.push_str(&pad);
    s.push(']');
    s
}
RS
"}

