use std::io::Write;
use std::path::PathBuf;
use std::sync::Mutex;

pub static LOG_FILE: Mutex<Option<std::fs::File>> = Mutex::new(None);

pub fn log_info(msg: &str) {
    if let Ok(mut guard) = LOG_FILE.lock() {
        if let Some(file) = guard.as_mut() {
            let now = chrono::Local::now();
            let _ = writeln!(file, "{} [INFO] {}", now.format("%H:%M:%S"), msg);
            let _ = file.flush();
        }
    }
}

fn setup_logging(args: &Args) -> anyhow::Result<()> {
    if let Some(path) = &args.log_file {
        let file = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)?;
        if let Ok(mut guard) = LOG_FILE.lock() {
            *guard = Some(file);
        }
        log_info(&format!("dua options={:#}", cli::debug_args(args)));
        let walk = WalkOptions {
            apparent_size: args.apparent_size,
            count_hard_links: args.count_hard_links,
            stay_on_filesystem: args.stay_on_filesystem,
            ignore_dirs: args.ignore_dirs.clone(),
        };
        let canon = walk.canonical_ignore_set();
        log_info(&format!("Ignoring canonicalized {:?}", canon));
    }
    Ok(())
}

fn real_main() -> anyhow::Result<i32> {
    let args = cli::parse();
    setup_logging(&args)?;
    let walk_opts = WalkOptions {
        apparent_size: args.apparent_size,
        count_hard_links: args.count_hard_links,
        stay_on_filesystem: args.stay_on_filesystem,
        ignore_dirs: args.ignore_dirs.clone(),
    };
    match &args.command {
        Some(CommandKind::Completions { shell }) => {
            let mut cmd = cli::build_cli();
            let name = cmd.get_name().to_string();
            let shell_gen = match shell {
                cli::Shell::Bash => clap_complete::Shell::Bash,
                cli::Shell::Elvish => clap_complete::Shell::Elvish,
                cli::Shell::Fish => clap_complete::Shell::Fish,
                cli::Shell::Powershell => clap_complete::Shell::PowerShell,
                cli::Shell::Zsh => clap_complete::Shell::Zsh,
            };
            clap_complete::generate(shell_gen, &mut cmd, name, &mut std::io::stdout());
            Ok(0)
        }
        Some(CommandKind::Aggregate {
            statistics,
            no_sort,
            no_total,
            input,
        }) => {
            let opts = aggregate::AggregateOptions {
                statistics: *statistics,
                no_sort: *no_sort,
                no_total: *no_total,
            };
            aggregate::run(input, &opts, &walk_opts, args.format)
        }
        Some(CommandKind::Interactive {
            no_entry_check,
            input,
        }) => interactive::run(input, *no_entry_check, &walk_opts, args.format),
        None => {
            // Implicit aggregate with default aggregate options.
            let opts = aggregate::AggregateOptions {
                statistics: false,
                no_sort: false,
                no_total: false,
            };
            aggregate::run(&args.input, &opts, &walk_opts, args.format)
        }
    }
}

fn main() {
    match real_main() {
        Ok(code) => {
            if code != 0 {
                std::process::exit(code);
            }
        }
        Err(err) => {
            eprintln!("Error: {}", err);
            std::process::exit(1);
        }
    }
}

