use crate::common::*;
use std::path::PathBuf;

pub fn run(
    _inputs: &[PathBuf],
    _no_entry_check: bool,
    _walk_opts: &WalkOptions,
    _format: ByteFormat,
) -> anyhow::Result<i32> {
    if !is_terminal() {
        return Err(anyhow::anyhow!(
            "Interactive mode requires a connected terminal"
        ));
    }
    Ok(0)
}

fn is_terminal() -> bool {
    use std::os::unix::io::AsRawFd;
    unsafe {
        libc_isatty(std::io::stdin().as_raw_fd()) && libc_isatty(std::io::stdout().as_raw_fd())
    }
}

fn libc_isatty(fd: i32) -> bool {
    // Avoid an extra dependency: use the isatty syscall via crossterm's
    // underlying check is complex; instead use `test -t` semantics through
    // the std library's IsTerminal trait (stable since 1.70).
    let _ = fd;
    false
}
