def test(name, stdin_mode, stdout_mode):
    master_out, slave_out = pty.openpty() if stdout_mode=='pty' else (None,None)
    master_in, slave_in = pty.openpty() if stdin_mode=='pty' else (None,None)
    stdin = slave_in if stdin_mode=='pty' else subprocess.PIPE
    stdout = slave_out if stdout_mode=='pty' else subprocess.PIPE
    p=subprocess.Popen(["/tmp/origbin/executable","i","/tmp/itest"], stdin=stdin, stdout=stdout, stderr=stdout, close_fds=True)
    time.sleep(1)
    alive=p.poll() is None
    data=b""
    if stdout_mode=='pty':
        while True:
            r,_,_=select.select([master_out],[],[],0.2)
            if not r: break
            try: chunk=os.read(master_out,65536)
            except: break
            if not chunk: break
            data+=chunk
    else:
        pass
    print(name, "alive",alive,"rc",p.poll(),"data len",len(data),data[:100])
    if alive:
        # try send q via appropriate
        try:
            if stdin_mode=='pty': os.write(master_in,b'q')
            elif p.stdin: p.stdin.write(b'q'); p.stdin.flush()
        except Exception as e: print(e)
        time.sleep(0.5)
        print(" after q alive",p.poll() is None,"rc",p.poll())
    if p.poll() is None: p.kill()
    p.wait()
for a,b in [('pipe','pty'),('pty','pipe')]:
    test(f"stdin={a} stdout={b}", a,b)
