use crate::common::*;
use crate::log_info;
use anyhow::Context;
use crossterm::{
    cursor,
    event::{self, Event, KeyCode, KeyEvent, KeyModifiers},
    execute,
    terminal::{self, EnterAlternateScreen, LeaveAlternateScreen},
};
use std::collections::{HashMap, HashSet};
use std::io::{IsTerminal, Write};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant, SystemTime};
use unicode_width::UnicodeWidthChar;

// ---------- styles ----------
#[derive(Clone, Copy, PartialEq, Debug)]
struct Style {
    fg: Option<u8>,
    bg: Option<u8>,
    bold: bool,
    underline: bool,
    reversed: bool,
    blink: bool,
}
impl Style {
    const fn plain() -> Self {
        Self { fg: None, bg: None, bold: false, underline: false, reversed: false, blink: false }
    }
    fn fg(mut self, c: u8) -> Self { self.fg = Some(c); self }
    fn bg(mut self, c: u8) -> Self { self.bg = Some(c); self }
    fn bold(mut self) -> Self { self.bold = true; self }
    fn underline(mut self) -> Self { self.underline = true; self }
    fn reversed(mut self) -> Self { self.reversed = true; self }
}

#[derive(Clone, PartialEq)]
struct Cell {
    ch: String,
    style: Style,
}
impl Default for Cell {
    fn default() -> Self { Self { ch: " ".to_string(), style: Style::plain() } }
}

struct Buffer {
    w: usize,
    h: usize,
    cells: Vec<Cell>,
}
impl Buffer {
    fn new(w: usize, h: usize) -> Self { Self { w, h, cells: vec![Cell::default(); w * h] } }
    fn set(&mut self, x: usize, y: usize, text: &str, style: Style) {
        self.set_limit(x, y, text, style, self.w);
    }
    fn set_limit(&mut self, mut x: usize, y: usize, text: &str, style: Style, limit: usize) {
        if y >= self.h { return; }
        for ch in text.chars() {
            if x >= limit || x >= self.w { break; }
            let width = UnicodeWidthChar::width(ch).unwrap_or(0);
            if width == 0 { continue; }
            let idx = y * self.w + x;
            self.cells[idx] = Cell { ch: ch.to_string(), style };
            // Fill continuation cells for wide characters.
            for i in 1..width {
                if x + i < self.w && x + i < limit {
                    let idx2 = y * self.w + x + i;
                    self.cells[idx2] = Cell { ch: String::new(), style };
                }
            }
            x += width;
        }
    }
    fn fill(&mut self, x: usize, y: usize, width: usize, style: Style) {
        for i in 0..width {
            if x + i < self.w && y < self.h {
                let idx = y * self.w + x + i;
                self.cells[idx].style = style;
                if self.cells[idx].ch.is_empty() { self.cells[idx].ch = " ".to_string(); }
            }
        }
    }
    fn hline(&mut self, x: usize, y: usize, width: usize, style: Style) {
        for i in 0..width { self.set(x + i, y, "─", style); }
    }
}

fn render_buffer(buf: &Buffer, out: &mut impl Write) -> anyhow::Result<()> {
    let mut s = String::new();
    let mut cur: Option<Style> = None;
    for y in 0..buf.h {
        s.push_str(&format!("\x1b[{};1H", y + 1));
        cur = None;
        for x in 0..buf.w {
            let cell = &buf.cells[y * buf.w + x];
            if cur != Some(cell.style) {
                s.push_str("\x1b[0m");
                let st = cell.style;
                if st.bold { s.push_str("\x1b[1m"); }
                if st.underline { s.push_str("\x1b[4m"); }
                if st.blink { s.push_str("\x1b[5m"); }
                if st.reversed { s.push_str("\x1b[7m"); }
                if let Some(c) = st.fg { s.push_str(&format!("\x1b[38;5;{}m", c)); }
                if let Some(c) = st.bg { s.push_str(&format!("\x1b[48;5;{}m", c)); }
                cur = Some(st);
            }
            if !cell.ch.is_empty() { s.push_str(&cell.ch); }
        }
    }
    s.push_str("\x1b[0m");
    out.write_all(s.as_bytes())?;
    out.flush()?;
    Ok(())
}

// ---------- graph ----------
type NodeId = usize;

#[derive(Clone)]
struct Node {
    alive: bool,
    parent: Option<NodeId>,
    children: Vec<NodeId>,
    name: String,
    title: String,
    fs_path: PathBuf,
    own_size: u64,
    size: u64,
    counted: bool,
    subtree_count: u64,
    mtime: SystemTime,
    is_dir: bool,
    is_symlink: bool,
}

struct Graph {
    nodes: Vec<Node>,
    top: NodeId,
    processed_entries: u64,
    processed_seconds: f64,
}

struct Builder<'a> {
    opts: &'a WalkOptions,
    state: TraversalState,
}

impl<'a> Builder<'a> {
    fn new_node(
        nodes: &mut Vec<Node>,
        parent: Option<NodeId>,
        name: String,
        title: String,
        fs_path: PathBuf,
    ) -> NodeId {
        let id = nodes.len();
        nodes.push(Node {
            alive: true,
            parent,
            children: Vec::new(),
            name,
            title,
            fs_path,
            own_size: 0,
            size: 0,
            counted: false,
            subtree_count: 0,
            mtime: SystemTime::UNIX_EPOCH,
            is_dir: false,
            is_symlink: false,
        });
        if let Some(p) = parent { nodes[p].children.push(id); }
        id
    }

    fn fill_node(
        &mut self,
        nodes: &mut Vec<Node>,
        id: NodeId,
        info: &EntryInfo,
    ) -> (u64, bool, bool) {
        let (size, dup) = crate::common::effective_size_flag(
            &mut self.state,
            &info.metadata,
            self.opts.apparent_size,
            self.opts.count_hard_links,
        );
        self.state.statistics.add(size);
        let n = &mut nodes[id];
        n.own_size = size;
        n.counted = !dup;
        n.mtime = mtime_of(&info.metadata);
        n.is_dir = info.is_real_dir;
        n.is_symlink = info.is_symlink;
        let root_dev = info.metadata.dev();
        (size, info.is_dir_follow, info.is_real_dir)
    }

    /// Build a subtree for an explicit traversal root. Returns None if the
    /// root cannot be stat'ed (following symlinks).
    fn build_root(
        &mut self,
        nodes: &mut Vec<Node>,
        parent: Option<NodeId>,
        fs_path: &Path,
        name: String,
        title: String,
    ) -> Option<NodeId> {
        let (info, root_dev) = get_info_root(fs_path)?;
        let id = Self::new_node(nodes, parent, name.clone(), title.clone(), fs_path.to_path_buf());
        let (_size, follow_dir, _real_dir) = self.fill_node(nodes, id, &info);
        if follow_dir {
            if !is_ignored(fs_path, &self.state) {
                self.build_children(nodes, id, fs_path, root_dev, &title);
            }
        }
        Some(id)
    }

    fn build_children(
        &mut self,
        nodes: &mut Vec<Node>,
        parent_id: NodeId,
        dir_path: &Path,
        root_dev: u64,
        parent_title: &str,
    ) {
        let read = match std::fs::read_dir(dir_path) { Ok(r) => r, Err(_) => return };
        let mut entries: Vec<PathBuf> = Vec::new();
        for e in read { if let Ok(e) = e { entries.push(e.path()); } }
        entries.sort_by(|a, b| a.file_name().cmp(&b.file_name()));
        for child_path in entries {
            self.build_nested(nodes, parent_id, &child_path, root_dev, parent_title);
        }
    }

    fn build_nested(
        &mut self,
        nodes: &mut Vec<Node>,
        parent_id: NodeId,
        fs_path: &Path,
        root_dev: u64,
        parent_title: &str,
    ) -> Option<NodeId> {
        let info = get_info_nested(fs_path)?;
        let name = fs_path
            .file_name()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_else(|| fs_path.to_string_lossy().into_owned());
        let title = if parent_title.is_empty() {
            name.clone()
        } else {
            format!("{}/{}", parent_title, name)
        };
        let id = Self::new_node(nodes, Some(parent_id), name, title.clone(), fs_path.to_path_buf());
        let (_s, _f, real_dir) = self.fill_node(nodes, id, &info);
        if real_dir {
            let descend = !is_ignored(fs_path, &self.state)
                && (!self.opts.stay_on_filesystem || info.metadata.dev() == root_dev);
            if descend {
                self.build_children(nodes, id, fs_path, root_dev, &title);
            }
        }
        Some(id)
    }
}

fn is_ignored(path: &Path, state: &TraversalState) -> bool {
    if state.ignore_set.is_empty() { return false; }
    match path.canonicalize() {
        Ok(c) => state.ignore_set.contains(&c),
        Err(_) => state.ignore_set.contains(path),
    }
}

fn recompute(nodes: &mut Vec<Node>, top: NodeId) {
    // Iterative post-order.
    let mut order: Vec<NodeId> = Vec::new();
    let mut stack = vec![top];
    while let Some(id) = stack.pop() {
        if !nodes[id].alive { continue; }
        order.push(id);
        for &c in &nodes[id].children { stack.push(c); }
    }
    for &id in order.iter().rev() {
        let mut size = nodes[id].own_size;
        let mut count: u64 = if nodes[id].counted { 1 } else { 0 };
        let children = nodes[id].children.clone();
        for c in children {
            if nodes[c].alive {
                size += nodes[c].size;
                count += nodes[c].subtree_count;
            }
        }
        nodes[id].size = size;
        nodes[id].subtree_count = count;
    }
}

fn build_graph(inputs: &[PathBuf], opts: &WalkOptions) -> anyhow::Result<Graph> {
    let start = Instant::now();
    let ignore_set = opts.canonical_ignore_set();
    let mut builder = Builder { opts, state: TraversalState::new(ignore_set) };
    let mut nodes: Vec<Node> = Vec::new();

    let single_dir: Option<PathBuf> = if inputs.len() == 1 && inputs[0].is_dir() {
        Some(inputs[0].clone())
    } else if inputs.is_empty() {
        Some(PathBuf::from("."))
    } else {
        None
    };

    let top: NodeId;
    if let Some(dir) = single_dir {
        let canonical = dir.canonicalize().unwrap_or_else(|_| {
            std::path::absolute(&dir).unwrap_or_else(|_| dir.clone())
        });
        let title = canonical.to_string_lossy().into_owned();
        top = Builder::new_node(&mut nodes, None, title.clone(), title, canonical.clone());
        // Top container itself is not counted.
        nodes[top].counted = false;
        nodes[top].own_size = 0;
        nodes[top].is_dir = true;
        // Expand the directory into child roots (this can fail, e.g. EACCES).
        let roots = expand_dir(&dir, opts)?;
        for root in roots {
            let name = root.display.to_string_lossy().into_owned();
            builder.build_root(&mut nodes, Some(top), &root.fs_path, name.clone(), name);
        }
    } else {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let title = cwd.to_string_lossy().into_owned();
        top = Builder::new_node(&mut nodes, None, title.clone(), title, cwd);
        nodes[top].counted = false;
        nodes[top].own_size = 0;
        nodes[top].is_dir = true;
        for input in inputs {
            log_info(&format!("Walking {:?}", input));
            let name = input.to_string_lossy().into_owned();
            builder.build_root(&mut nodes, Some(top), input, name.clone(), name);
        }
    }
    // Interactive traversal logs in the original only appear for the
    // artificial-root mode; harmless to emit there (already done above).
    recompute(&mut nodes, top);
    let processed_entries = builder.state.statistics.entries_traversed;
    Ok(Graph {
        nodes,
        top,
        processed_entries,
        processed_seconds: start.elapsed().as_secs_f64(),
    })
}

// ---------- sorting ----------
#[derive(Clone, Copy, PartialEq)]
enum SortMode {
    SizeDescending,
    SizeAscending,
    NameAscending,
    NameDescending,
    ModifiedDescending,
    ModifiedAscending,
    ItemsDescending,
    ItemsAscending,
}
impl SortMode {
    fn label(&self) -> &'static str {
        match self {
            Self::SizeDescending => "size descending",
            Self::SizeAscending => "size ascending",
            Self::NameAscending => "name ascending",
            Self::NameDescending => "name descending",
            Self::ModifiedDescending => "modified descending",
            Self::ModifiedAscending => "modified ascending",
            Self::ItemsDescending => "items descending",
            Self::ItemsAscending => "items ascending",
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
enum GaugeMode { Both, PercentOnly, BarOnly, LargeBar }

#[derive(Clone, Copy, PartialEq)]
enum Focus { Main, Marked, Help, Search }

struct SearchResult {
    node: NodeId,
    display: String,
}

struct App {
    graph: Graph,
    inputs: Vec<PathBuf>,
    walk_opts: WalkOptions,
    format: ByteFormat,
    no_entry_check: bool,
    current: NodeId,
    selection: usize,
    offset: usize,
    view_memory: HashMap<NodeId, (usize, usize)>,
    sort_mode: SortMode,
    gauge_mode: GaugeMode,
    show_mtime: bool,
    show_count: bool,
    marked: Vec<NodeId>,
    marked_set: HashSet<NodeId>,
    marked_selection: usize,
    marked_offset: usize,
    marked_armed: bool,
    marked_prompt: bool,
    focus: Focus,
    help_open: bool,
    help_scroll: usize,
    search_open: bool,
    search_input_focus: bool,
    search_text: String,
    search_case_sensitive: bool,
    search_results: Vec<SearchResult>,
    status_message: Option<String>,
    quit: bool,
}

impl App {
    fn node(&self, id: NodeId) -> &Node { &self.graph.nodes[id] }

    fn sorted_children(&self, parent: NodeId) -> Vec<NodeId> {
        let mut ids: Vec<NodeId> = self
            .node(parent)
            .children
            .iter()
            .copied()
            .filter(|&c| self.node(c).alive)
            .collect();
        self.sort_ids(&mut ids, |app, id| app.node(id).name.clone());
        ids
    }

    fn sort_ids(&self, ids: &mut Vec<NodeId>, name_of: impl Fn(&Self, NodeId) -> String) {
        let nodes = &self.graph.nodes;
        let mode = self.sort_mode;
        // Precompute names to avoid borrowing problems.
        let names: HashMap<NodeId, String> = ids.iter().map(|&id| (id, name_of(self, id))).collect();
        ids.sort_by(|&a, &b| {
            let na = &nodes[a];
            let nb = &nodes[b];
            let name_a = names.get(&a).map(|s| s.as_str()).unwrap_or("");
            let name_b = names.get(&b).map(|s| s.as_str()).unwrap_or("");
            match mode {
                SortMode::SizeDescending => nb.size.cmp(&na.size).then_with(|| name_b.cmp(name_a)),
                SortMode::SizeAscending => na.size.cmp(&nb.size).then_with(|| name_b.cmp(name_a)),
                SortMode::ModifiedDescending => nb.mtime.cmp(&na.mtime).then_with(|| name_b.cmp(name_a)),
                SortMode::ModifiedAscending => na.mtime.cmp(&nb.mtime).then_with(|| name_b.cmp(name_a)),
                SortMode::NameAscending => nb.is_dir.cmp(&na.is_dir).then_with(|| name_a.cmp(name_b)),
                SortMode::NameDescending => na.is_dir.cmp(&nb.is_dir).then_with(|| name_b.cmp(name_a)),
                SortMode::ItemsDescending => nb.subtree_count.cmp(&na.subtree_count).then_with(|| name_b.cmp(name_a)),
                SortMode::ItemsAscending => na.subtree_count.cmp(&nb.subtree_count).then_with(|| name_a.cmp(name_b)),
            }
        });
    }

    fn display_entries(&self) -> Vec<(NodeId, String)> {
        if self.search_open && !self.search_results.is_empty() || (self.search_open && self.applied_search()) {
            let mut ids: Vec<NodeId> = self.search_results.iter().map(|r| r.node).collect();
            let disp: HashMap<NodeId, String> = self
                .search_results
                .iter()
                .map(|r| (r.node, r.display.clone()))
                .collect();
            self.sort_ids(&mut ids, |_app, id| {
                disp.get(&id).cloned().unwrap_or_default()
            });
            // NOTE: sorting by display here approximates the original; the
            // display string for search entries is the relative path.
            return ids
                .into_iter()
                .map(|id| (id, disp.get(&id).cloned().unwrap_or_default()))
                .collect();
        }
        self.sorted_children(self.current)
            .into_iter()
            .map(|id| (id, self.node(id).name.clone()))
            .collect()
    }

    fn applied_search(&self) -> bool {
        self.search_open && !self.search_input_focus && !self.search_results.is_empty()
    }

    fn current_entries(&self) -> Vec<(NodeId, String)> { self.display_entries() }

    fn clamp_selection(&mut self) {
        let len = self.current_entries().len();
        if len == 0 { self.selection = 0; self.offset = 0; }
        else if self.selection >= len { self.selection = len - 1; }
    }

    fn selected_node(&self) -> Option<NodeId> {
        self.current_entries().get(self.selection).map(|e| e.0)
    }

    fn set_current(&mut self, new_current: NodeId) {
        let old = self.current;
        self.view_memory.insert(old, (self.selection, self.offset));
        self.current = new_current;
        let (sel, off) = self.view_memory.get(&new_current).copied().unwrap_or((0, 0));
        self.selection = sel;
        self.offset = off;
        if !self.no_entry_check {
            self.prune_missing_children(new_current);
        }
        self.clamp_selection();
    }

    fn prune_missing_children(&mut self, parent: NodeId) {
        let children = self.node(parent).children.clone();
        let mut removed_any = false;
        for child in children {
            if !self.node(child).alive { continue; }
            let path = self.node(child).fs_path.clone();
            if std::fs::symlink_metadata(&path).is_err() {
                self.remove_subtree(child);
                removed_any = true;
            }
        }
        if removed_any { recompute(&mut self.graph.nodes, self.graph.top); }
    }

    fn remove_subtree(&mut self, id: NodeId) {
        // Mark subtree dead and detach from parent.
        let mut stack = vec![id];
        let mut all = Vec::new();
        while let Some(n) = stack.pop() {
            all.push(n);
            for &c in &self.graph.nodes[n].children { stack.push(c); }
        }
        for &n in &all {
            self.graph.nodes[n].alive = false;
            self.marked_set.remove(&n);
        }
        self.marked.retain(|&m| self.graph.nodes[m].alive);
        if let Some(parent) = self.graph.nodes[id].parent {
            self.graph.nodes[parent].children.retain(|&c| c != id);
        }
    }

    fn toggle_mark(&mut self, id: NodeId) {
        if self.marked_set.contains(&id) {
            self.marked_set.remove(&id);
            self.marked.retain(|&m| m != id);
            if self.marked.is_empty() { self.marked_armed = false; self.marked_prompt = false; }
        } else {
            self.marked_set.insert(id);
            self.marked.push(id);
            self.marked_armed = true;
        }
        if self.marked_selection >= self.marked.len() && !self.marked.is_empty() {
            self.marked_selection = self.marked.len() - 1;
        }
    }

    fn move_selection(&mut self, delta: isize) {
        let len = self.current_entries().len();
        if len == 0 { return; }
        let mut sel = self.selection as isize + delta;
        sel = sel.clamp(0, len as isize - 1);
        self.selection = sel as usize;
    }

    fn rebuild_subtree_from_disk(&mut self, id: NodeId) {
        // Rebuild a node's subtree by re-walking its path.
        let path = self.node(id).fs_path.clone();
        let parent = self.node(id).parent;
        let name = self.node(id).name.clone();
        let title = self.node(id).title.clone();
        // Detach and discard old descendants.
        let old_children = self.node(id).children.clone();
        for &child in &old_children {
            // Remove grandchildren subtrees by marking descendants dead
            // (except the child roots, which are replaced below).
            let mut stack = vec![child];
            while let Some(n) = stack.pop() {
                self.graph.nodes[n].alive = false;
                for &c in &self.graph.nodes[n].children { stack.push(c); }
            }
        }
        self.graph.nodes[id].children.clear();
        self.marked.retain(|&m| self.graph.nodes[m].alive);
        self.marked_set.retain(|&m| self.graph.nodes[m].alive);

        // Fresh builder with fresh stats / hard-link state for this refresh.
        let ignore_set = self.walk_opts.canonical_ignore_set();
        let mut builder = Builder {
            opts: &self.walk_opts,
            state: TraversalState::new(ignore_set),
        };
        let start = Instant::now();
        // Fill this node itself again as an explicit root.
        if let Some((info, root_dev)) = get_info_root(&path) {
            let (_s, follow_dir, _rd) = builder.fill_node(&mut self.graph.nodes, id, &info);
            // Restore identity fields potentially overwritten in spirit.
            self.graph.nodes[id].name = name.clone();
            self.graph.nodes[id].title = title.clone();
            self.graph.nodes[id].fs_path = path.clone();
            if follow_dir && !is_ignored(&path, &builder.state) {
                builder.build_children(&mut self.graph.nodes, id, &path, root_dev, &title);
            }
        } else {
            // Vanished: remove node entirely.
            let _ = parent;
            self.remove_subtree(id);
        }
        recompute(&mut self.graph.nodes, self.graph.top);
        self.graph.processed_entries = builder.state.statistics.entries_traversed;
        self.graph.processed_seconds = start.elapsed().as_secs_f64();
    }

    fn refresh_selected(&mut self) {
        if let Some(id) = self.selected_node() {
            self.rebuild_subtree_from_disk(id);
            self.clamp_selection();
        }
    }

    fn refresh_all_in_view(&mut self) {
        let entries: Vec<NodeId> = self.current_entries().iter().map(|e| e.0).collect();
        let mut total_entries: u64 = 0;
        let start = Instant::now();
        for id in entries {
            if !self.node(id).alive { continue; }
            // Inline a refresh but aggregate stats.
            let before_nodes_len = self.graph.nodes.len();
            let _ = before_nodes_len;
            self.rebuild_subtree_from_disk(id);
            total_entries += self.graph.processed_entries;
        }
        self.graph.processed_entries = total_entries;
        self.graph.processed_seconds = start.elapsed().as_secs_f64();
        self.clamp_selection();
    }

    fn do_delete(&mut self, trash: bool) {
        let marked = self.marked.clone();
        let mut removed: Vec<NodeId> = Vec::new();
        for &id in &marked {
            if !self.node(id).alive { continue; }
            let path = self.node(id).fs_path.clone();
            let result = if trash {
                trash_path(&path)
            } else {
                delete_path(&path)
            };
            if result.is_ok() || !path.exists() && !std::fs::symlink_metadata(&path).is_ok() {
                removed.push(id);
            } else if result.is_ok() {
                removed.push(id);
            }
        }
        // Remove successfully deleted (or already gone) nodes from graph.
        // If removal failed and the path still exists, keep it.
        for &id in &marked {
            if !self.node(id).alive { continue; }
            let path = self.node(id).fs_path.clone();
            if std::fs::symlink_metadata(&path).is_err() {
                // Gone from disk -> remove node.
                let was_current_or_ancestor = {
                    let mut cur = Some(self.current);
                    let mut found = false;
                    while let Some(n) = cur {
                        if n == id { found = true; break; }
                        cur = self.graph.nodes[n].parent;
                    }
                    found
                };
                self.remove_subtree(id);
                if was_current_or_ancestor {
                    // Move current to the top node (which survives unless it
                    // itself was removed; top is artificial/single root).
                    self.current = self.graph.top;
                    self.selection = 0;
                    self.offset = 0;
                }
            }
        }
        self.marked.clear();
        self.marked_set.clear();
        self.marked_armed = false;
        self.marked_prompt = false;
        self.focus = Focus::Main;
        recompute(&mut self.graph.nodes, self.graph.top);
        self.clamp_selection();
        let _ = removed;
    }
}

fn delete_path(path: &Path) -> std::io::Result<()> {
    let meta = std::fs::symlink_metadata(path)?;
    if meta.is_dir() {
        std::fs::remove_dir_all(path)
    } else {
        std::fs::remove_file(path)
    }
}

fn trash_path(path: &Path) -> anyhow::Result<()> {
    let data_home = std::env::var_os("XDG_DATA_HOME")
        .map(PathBuf::from)
        .filter(|p| p.is_absolute())
        .unwrap_or_else(|| {
            let home = std::env::var_os("HOME").map(PathBuf::from).unwrap_or_else(|| PathBuf::from("~"));
            home.join(".local").join("share")
        });
    let trash_files = data_home.join("Trash").join("files");
    let trash_info = data_home.join("Trash").join("info");
    std::fs::create_dir_all(&trash_files)?;
    std::fs::create_dir_all(&trash_info)?;
    let file_name = path
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "trashed".to_string());
    let mut dest_name = file_name.clone();
    let mut counter = 1;
    while trash_files.join(&dest_name).exists() || trash_info.join(format!("{}.trashinfo", dest_name)).exists() {
        dest_name = format!("{}.{}", file_name, counter);
        counter += 1;
    }
    let absolute = std::path::absolute(path).unwrap_or_else(|_| path.to_path_buf());
    let info_content = format!(
        "[Trash Info]\nPath={}\nDeletionDate={}\n",
        absolute.display(),
        chrono::Local::now().format("%Y-%m-%dT%H:%M:%S")
    );
    std::fs::write(trash_info.join(format!("{}.trashinfo", dest_name)), info_content)?;
    let dest = trash_files.join(&dest_name);
    if std::fs::rename(path, &dest).is_err() {
        // Cross-device fallback: copy then remove.
        let meta = std::fs::symlink_metadata(path)?;
        if meta.is_dir() {
            copy_dir(path, &dest)?;
            std::fs::remove_dir_all(path)?;
        } else if meta.file_type().is_symlink() {
            let target = std::fs::read_link(path)?;
            std::os::unix::fs::symlink(&target, &dest)?;
            std::fs::remove_file(path)?;
        } else {
            std::fs::copy(path, &dest)?;
            std::fs::remove_file(path)?;
        }
    }
    Ok(())
}

fn copy_dir(src: &Path, dst: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(dst)?;
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let from = entry.path();
        let to = dst.join(entry.file_name());
        let meta = std::fs::symlink_metadata(&from)?;
        if meta.is_dir() {
            copy_dir(&from, &to)?;
        } else if meta.file_type().is_symlink() {
            let target = std::fs::read_link(&from)?;
            std::os::unix::fs::symlink(&target, &to)?;
        } else {
            std::fs::copy(&from, &to)?;
        }
    }
    Ok(())
}

// ---------- text helpers ----------
fn truncate_middle(text: &str, max_width: usize) -> String {
    use unicode_width::UnicodeWidthStr;
    let width = UnicodeWidthStr::width(text);
    if width <= max_width { return text.to_string(); }
    if max_width == 0 { return String::new(); }
    if max_width == 1 { return "…".to_string(); }
    let avail = max_width - 1; // ellipsis
    let start_w = avail / 2;
    let end_w = avail - start_w;
    // Collect start grapheme-ish chars by width.
    let mut start = String::new();
    let mut w = 0;
    for ch in text.chars() {
        let cw = UnicodeWidthChar::width(ch).unwrap_or(0);
        if w + cw > start_w { break; }
        start.push(ch);
        w += cw;
    }
    let mut end_chars: Vec<char> = Vec::new();
    let mut w = 0;
    for ch in text.chars().rev() {
        let cw = UnicodeWidthChar::width(ch).unwrap_or(0);
        if w + cw > end_w { break; }
        end_chars.push(ch);
        w += cw;
    }
    end_chars.reverse();
    let end: String = end_chars.into_iter().collect();
    format!("{}…{}", start, end)
}

fn bar_string(fraction: f64, width: usize) -> String {
    let mut eighths = (fraction.clamp(0.0, 1.0) * (width as f64) * 8.0).round() as usize;
    let max = width * 8;
    if eighths > max { eighths = max; }
    let full = eighths / 8;
    let rem = eighths % 8;
    const PARTS: [&str; 8] = ["", "▏", "▎", "▍", "▌", "▋", "▊", "▉"];
    let mut s = String::new();
    for _ in 0..full { s.push('█'); }
    let mut used = full;
    if rem > 0 && full < width {
        s.push_str(PARTS[rem]);
        used += 1;
    }
    for _ in used..width { s.push(' '); }
    s
}

fn scrollbar_cells(viewport: usize, content: usize, selected: usize) -> Vec<bool> {
    // true = thumb, false = track
    if content == 0 || viewport == 0 { return vec![false; viewport]; }
    let thumb = if content == 1 {
        viewport
    } else {
        (((viewport * viewport) as f64) / ((content + viewport - 1) as f64)).round() as usize
    };
    let thumb = thumb.clamp(1, viewport);
    let start = if content <= 1 {
        0
    } else {
        ((selected as f64) * ((viewport - thumb) as f64) / ((content - 1) as f64)).round() as usize
    };
    let start = start.min(viewport - thumb);
    (0..viewport).map(|i| i >= start && i < start + thumb).collect()
}

// ---------- main entry ----------
pub fn run(
    inputs: &[PathBuf],
    no_entry_check: bool,
    walk_opts: &WalkOptions,
    format: ByteFormat,
) -> anyhow::Result<i32> {
    if !std::io::stdout().is_terminal() {
        anyhow::bail!("Interactive mode requires a connected terminal");
    }
    // Build the graph before entering the terminal, matching the observed
    // hard error for an unreadable single directory (Error: ...).
    // Terminal setup first, however, is what produces the connected-terminal
    // error context for a tty stdout with a non-tty stdin.
    terminal::enable_raw_mode().context("Interactive mode requires a connected terminal")?;
    let mut stdout = std::io::stdout();
    let setup = (|| -> anyhow::Result<()> {
        execute!(stdout, EnterAlternateScreen, cursor::Hide, terminal::Clear(terminal::ClearType::All))?;
        Ok(())
    })();
    if let Err(e) = setup {
        let _ = terminal::disable_raw_mode();
        return Err(e.context("Interactive mode requires a connected terminal"));
    }

    let result = run_app(&mut stdout, inputs, no_entry_check, walk_opts, format);

    let _ = execute!(stdout, cursor::Show, LeaveAlternateScreen);
    let _ = terminal::disable_raw_mode();
    result
}

fn run_app(
    stdout: &mut impl Write,
    inputs: &[PathBuf],
    no_entry_check: bool,
    walk_opts: &WalkOptions,
    format: ByteFormat,
) -> anyhow::Result<i32> {
    let graph = build_graph(inputs, walk_opts)?;
    let mut app = App {
        current: graph.top,
        graph,
        inputs: inputs.to_vec(),
        walk_opts: walk_opts.clone(),
        format,
        no_entry_check,
        selection: 0,
        offset: 0,
        view_memory: HashMap::new(),
        sort_mode: SortMode::SizeDescending,
        gauge_mode: GaugeMode::Both,
        show_mtime: false,
        show_count: false,
        marked: Vec::new(),
        marked_set: HashSet::new(),
        marked_selection: 0,
        marked_offset: 0,
        marked_armed: false,
        marked_prompt: false,
        focus: Focus::Main,
        help_open: false,
        help_scroll: 0,
        search_open: false,
        search_input_focus: false,
        search_text: String::new(),
        search_case_sensitive: false,
        search_results: Vec::new(),
        status_message: None,
        quit: false,
    };
    draw(stdout, &mut app)?;
    loop {
        if app.quit { break; }
        let ev = event::read()?;
        match ev {
            Event::Key(key) => {
                if key.kind == event::KeyEventKind::Release { continue; }
                handle_key(&mut app, key);
                draw(stdout, &mut app)?;
            }
            Event::Resize(_, _) => {
                draw(stdout, &mut app)?;
            }
            _ => {}
        }
    }
    Ok(0)
}

fn is_ctrl(key: &KeyEvent, c: char) -> bool {
    key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char(c)
}

// Glob matching (git-style, simplified).
fn glob_matches(pattern: &str, path: &str, basename: &str, case_sensitive: bool) -> bool {
    let (pat, target_path, target_base) = if case_sensitive {
        (pattern.to_string(), path.to_string(), basename.to_string())
    } else {
        (pattern.to_lowercase(), path.to_lowercase(), basename.to_lowercase())
    };
    if pat.contains('/') {
        wildcard_match(&pat, &target_path)
    } else {
        wildcard_match(&pat, &target_base)
    }
}

fn wildcard_match(pattern: &str, text: &str) -> bool {
    // Convert to a simple DP wildcard matcher supporting *, **, ?, [..]
    let p: Vec<char> = pattern.chars().collect();
    let t: Vec<char> = text.chars().collect();
    wildcard_rec(&p, 0, &t, 0)
}

fn wildcard_rec(p: &[char], mut pi: usize, t: &[char], mut ti: usize) -> bool {
    while pi < p.len() {
        match p[pi] {
            '*' => {
                // Collapse consecutive stars. `**` crosses `/`; a single
                // star also crosses when matching a basename (no `/` can
                // occur). For path matching we approximate git behaviour:
                // a lone `*` does not cross `/`, `**` does.
                let is_double = pi + 1 < p.len() && p[pi + 1] == '*';
                if is_double {
                    // ** can match any number of chars, and `**/` can match empty.
                    let mut rest_pi = pi + 2;
                    if rest_pi < p.len() && p[rest_pi] == '/' { rest_pi += 1; }
                    for skip in ti..=t.len() {
                        if wildcard_rec(p, rest_pi, t, skip) { return true; }
                    }
                    return false;
                } else {
                    for skip in ti..=t.len() {
                        if skip > ti && t[skip - 1] == '/' { break; }
                        if wildcard_rec(p, pi + 1, t, skip) { return true; }
                    }
                    return false;
                }
            }
            '?' => {
                if ti >= t.len() || t[ti] == '/' { return false; }
                pi += 1; ti += 1;
            }
            '[' => {
                if ti >= t.len() { return false; }
                let mut j = pi + 1;
                let neg = j < p.len() && (p[j] == '!' || p[j] == '^');
                if neg { j += 1; }
                let mut matched = false;
                let mut first = true;
                while j < p.len() && (p[j] != ']' || first) {
                    first = false;
                    if j + 2 < p.len() && p[j + 1] == '-' && p[j + 2] != ']' {
                        if p[j] <= t[ti] && t[ti] <= p[j + 2] { matched = true; }
                        j += 3;
                    } else {
                        if p[j] == t[ti] { matched = true; }
                        j += 1;
                    }
                }
                if j >= p.len() {
                    // No closing bracket: treat '[' literally.
                    if t[ti] != '[' { return false; }
                    pi += 1; ti += 1;
                } else {
                    if matched == neg { return false; }
                    pi = j + 1; ti += 1;
                }
            }
            '\\' if pi + 1 < p.len() => {
                if ti >= t.len() || t[ti] != p[pi + 1] { return false; }
                pi += 2; ti += 1;
            }
            c => {
                if ti >= t.len() || t[ti] != c { return false; }
                pi += 1; ti += 1;
            }
        }
    }
    ti == t.len()
}

fn apply_search(app: &mut App) {
    let pattern = app.search_text.clone();
    let mut results = Vec::new();
    let current = app.current;
    fn collect(
        app: &App,
        node: NodeId,
        prefix: &str,
        pattern: &str,
        case_sensitive: bool,
        out: &mut Vec<SearchResult>,
    ) {
        let children = app.node(node).children.clone();
        for child in children {
            if !app.node(child).alive { continue; }
            let name = app.node(child).name.clone();
            let rel = if prefix.is_empty() { name.clone() } else { format!("{}/{}", prefix, name) };
            // For children of the top node whose names are full input paths,
            // the relative path is still that name (matching the UI).
            let basename = app
                .node(child)
                .fs_path
                .file_name()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_else(|| name.clone());
            if glob_matches(pattern, &rel, &basename, case_sensitive) {
                out.push(SearchResult { node: child, display: rel.clone() });
            }
            collect(app, child, &rel, pattern, case_sensitive, out);
        }
    }
    collect(app, current, "", &pattern, app.search_case_sensitive, &mut results);
    if results.is_empty() {
        app.status_message = Some("No match found".to_string());
        // Stay in search input focus.
        app.search_input_focus = true;
        app.focus = Focus::Search;
    } else {
        app.search_results = results;
        app.search_input_focus = false;
        app.focus = Focus::Main;
        app.selection = 0;
        app.offset = 0;
    }
}

fn handle_key(app: &mut App, key: KeyEvent) {
    // Ctrl+c closes the application from anywhere.
    if is_ctrl(&key, 'c') {
        app.quit = true;
        return;
    }
    let had_message = app.status_message.take();
    let _ = had_message;
    app.status_message = None;

    match app.focus {
        Focus::Search => {
            handle_search_key(app, key);
            return;
        }
        Focus::Help => {
            handle_help_key(app, key);
            return;
        }
        Focus::Marked => {
            handle_marked_key(app, key);
            return;
        }
        Focus::Main => {}
    }

    // Main focus.
    match key.code {
        KeyCode::Char('q') => close_pane(app),
        KeyCode::Esc => close_pane(app),
        KeyCode::Tab => {
            if app.help_open {
                app.focus = Focus::Help;
            } else if !app.marked.is_empty() {
                app.focus = Focus::Marked;
                app.marked_prompt = true;
            }
        }
        KeyCode::Char('?') => {
            app.help_open = true;
            app.focus = Focus::Help;
            app.help_scroll = 0;
        }
        KeyCode::Char('/') => {
            app.search_open = true;
            app.search_input_focus = true;
            app.focus = Focus::Search;
            app.search_text.clear();
        }
        KeyCode::Char('j') | KeyCode::Down => app.move_selection(1),
        KeyCode::Char('k') | KeyCode::Up => app.move_selection(-1),
        KeyCode::Char('H') | KeyCode::Home => {
            app.selection = 0;
        }
        KeyCode::Char('G') | KeyCode::End => {
            let len = app.current_entries().len();
            if len > 0 { app.selection = len - 1; }
        }
        _ if is_ctrl(&key, 'd') => app.move_selection(10),
        KeyCode::PageDown => app.move_selection(10),
        _ if is_ctrl(&key, 'u') => app.move_selection(-10),
        KeyCode::PageUp => app.move_selection(-10),
        KeyCode::Char('o') | KeyCode::Char('l') | KeyCode::Enter | KeyCode::Right => descend(app),
        KeyCode::Char('u') | KeyCode::Char('h') | KeyCode::Left | KeyCode::Backspace => ascend(app),
        KeyCode::Char('s') => {
            app.sort_mode = if app.sort_mode == SortMode::SizeDescending {
                SortMode::SizeAscending
            } else {
                SortMode::SizeDescending
            };
        }
        KeyCode::Char('n') => {
            app.sort_mode = if app.sort_mode == SortMode::NameAscending {
                SortMode::NameDescending
            } else {
                SortMode::NameAscending
            };
        }
        KeyCode::Char('m') if !key.modifiers.contains(KeyModifiers::CONTROL) => {
            // lowercase m (shift distinguishes 'M')
            app.sort_mode = if app.sort_mode == SortMode::ModifiedDescending {
                SortMode::ModifiedAscending
            } else {
                SortMode::ModifiedDescending
            };
        }
        KeyCode::Char('M') => {
            app.show_mtime = !app.show_mtime;
        }
        KeyCode::Char('c') => {
            app.sort_mode = if app.sort_mode == SortMode::ItemsDescending {
                SortMode::ItemsAscending
            } else {
                SortMode::ItemsDescending
            };
        }
        KeyCode::Char('C') => {
            app.show_count = !app.show_count;
        }
        KeyCode::Char('g') | KeyCode::Char('S') => {
            app.gauge_mode = match app.gauge_mode {
                GaugeMode::Both => GaugeMode::PercentOnly,
                GaugeMode::PercentOnly => GaugeMode::BarOnly,
                GaugeMode::BarOnly => GaugeMode::LargeBar,
                GaugeMode::LargeBar => GaugeMode::Both,
            };
        }
        KeyCode::Char('O') => {
            if let Some(id) = app.selected_node() {
                let path = app.node(id).fs_path.clone();
                let _ = std::process::Command::new("xdg-open")
                    .arg(&path)
                    .stdin(std::process::Stdio::null())
                    .stdout(std::process::Stdio::null())
                    .stderr(std::process::Stdio::null())
                    .spawn();
            }
        }
        KeyCode::Char(' ') => {
            if let Some(id) = app.selected_node() {
                app.toggle_mark(id);
            }
        }
        KeyCode::Char('d') => {
            if let Some(id) = app.selected_node() {
                app.toggle_mark(id);
                app.move_selection(1);
            }
        }
        KeyCode::Char('x') => {
            if let Some(id) = app.selected_node() {
                if !app.marked_set.contains(&id) {
                    app.toggle_mark(id);
                }
                app.move_selection(1);
            }
        }
        KeyCode::Char('a') => {
            let entries: Vec<NodeId> = app.current_entries().iter().map(|e| e.0).collect();
            for id in entries { app.toggle_mark(id); }
        }
        KeyCode::Char('r') => app.refresh_selected(),
        KeyCode::Char('R') => app.refresh_all_in_view(),
        _ => {}
    }
}

fn descend(app: &mut App) {
    let Some(id) = app.selected_node() else { return };
    if app.node(id).children.iter().any(|&c| app.node(c).alive) {
        // Leaving a search view into a directory clears the search display.
        let was_search = app.search_open;
        app.set_current(id);
        if was_search {
            app.search_open = false;
            app.search_results.clear();
            app.search_text.clear();
        }
    } else {
        app.status_message = Some("Entry is a file or an empty directory".to_string());
    }
}

fn ascend(app: &mut App) {
    if app.search_open && !app.search_results.is_empty() {
        // Ascending from a search view first clears the search? The original
        // restores the full listing with Esc; `u` from search results goes up.
    }
    if let Some(parent) = app.node(app.current).parent {
        app.set_current(parent);
        if app.search_open {
            app.search_results.clear();
            // Keep search pane state consistent with leaving the directory.
            app.search_open = false;
            app.search_text.clear();
        }
    } else {
        app.status_message = Some("Top level reached".to_string());
    }
}

fn close_pane(app: &mut App) {
    match app.focus {
        Focus::Help => {
            app.help_open = false;
            app.focus = Focus::Main;
        }
        Focus::Marked => {
            app.focus = Focus::Main;
            // marked_prompt intentionally stays as observed.
        }
        Focus::Search => {
            app.search_open = false;
            app.search_input_focus = false;
            app.search_results.clear();
            app.search_text.clear();
            app.focus = Focus::Main;
        }
        Focus::Main => {
            if app.help_open {
                // Help is open but not focused: q exits (observed).
                app.quit = true;
            } else if app.marked_armed && !app.marked.is_empty() {
                app.marked_armed = false;
            } else {
                app.quit = true;
            }
        }
    }
}

fn handle_help_key(app: &mut App, key: KeyEvent) {
    let viewport = 20usize; // corrected during draw; use a sane default for paging
    match key.code {
        KeyCode::Char('q') | KeyCode::Esc => {
            app.help_open = false;
            app.focus = Focus::Main;
        }
        KeyCode::Char('?') => {
            app.help_open = false;
            app.focus = Focus::Main;
        }
        KeyCode::Tab => {
            app.focus = Focus::Main;
        }
        KeyCode::Char('j') | KeyCode::Down => { app.help_scroll += 1; }
        KeyCode::Char('k') | KeyCode::Up => { app.help_scroll = app.help_scroll.saturating_sub(1); }
        _ if is_ctrl(&key, 'd') => { app.help_scroll += 10; }
        KeyCode::PageDown => { app.help_scroll += 10; }
        _ if is_ctrl(&key, 'u') => { app.help_scroll = app.help_scroll.saturating_sub(10); }
        KeyCode::PageUp => { app.help_scroll = app.help_scroll.saturating_sub(10); }
        KeyCode::Char('H') | KeyCode::Home => { app.help_scroll = 0; }
        KeyCode::Char('G') | KeyCode::End => { app.help_scroll = usize::MAX / 2; }
        _ => { let _ = viewport; }
    }
}

fn handle_marked_key(app: &mut App, key: KeyEvent) {
    let len = app.marked.len();
    match key.code {
        KeyCode::Char('q') | KeyCode::Esc => {
            app.focus = Focus::Main;
        }
        KeyCode::Tab => {
            app.focus = Focus::Main;
            app.marked_prompt = false;
        }
        KeyCode::Char('?') => {
            app.help_open = true;
            app.focus = Focus::Help;
        }
        KeyCode::Char('j') | KeyCode::Down => {
            if len > 0 && app.marked_selection + 1 < len { app.marked_selection += 1; }
        }
        KeyCode::Char('k') | KeyCode::Up => {
            app.marked_selection = app.marked_selection.saturating_sub(1);
        }
        _ if is_ctrl(&key, 'd') => {
            if len > 0 { app.marked_selection = (app.marked_selection + 10).min(len - 1); }
        }
        KeyCode::PageDown => {
            if len > 0 { app.marked_selection = (app.marked_selection + 10).min(len - 1); }
        }
        _ if is_ctrl(&key, 'u') => {
            app.marked_selection = app.marked_selection.saturating_sub(10);
        }
        KeyCode::PageUp => {
            app.marked_selection = app.marked_selection.saturating_sub(10);
        }
        KeyCode::Char('H') | KeyCode::Home => app.marked_selection = 0,
        KeyCode::Char('G') | KeyCode::End => {
            if len > 0 { app.marked_selection = len - 1; }
        }
        KeyCode::Char('x') | KeyCode::Char('d') | KeyCode::Char(' ') => {
            if len > 0 {
                let id = app.marked[app.marked_selection];
                app.toggle_mark(id);
                if app.marked.is_empty() {
                    app.focus = Focus::Main;
                    app.marked_prompt = false;
                } else if app.marked_selection >= app.marked.len() {
                    app.marked_selection = app.marked.len() - 1;
                }
            }
        }
        KeyCode::Char('a') => {
            app.marked.clear();
            app.marked_set.clear();
            app.marked_armed = false;
            app.marked_prompt = false;
            app.focus = Focus::Main;
        }
        _ if is_ctrl(&key, 'r') => {
            app.do_delete(false);
        }
        _ if is_ctrl(&key, 't') => {
            app.do_delete(true);
        }
        _ => {}
    }
}

fn handle_search_key(app: &mut App, key: KeyEvent) {
    match key.code {
        KeyCode::Esc => {
            app.search_open = false;
            app.search_input_focus = false;
            app.search_results.clear();
            app.search_text.clear();
            app.focus = Focus::Main;
        }
        KeyCode::Enter => {
            apply_search(app);
        }
        KeyCode::Backspace => {
            app.search_text.pop();
        }
        _ if is_ctrl(&key, 'f') => {
            app.search_case_sensitive = !app.search_case_sensitive;
        }
        KeyCode::Char(c) => {
            if !key.modifiers.contains(KeyModifiers::CONTROL) {
                app.search_text.push(c);
            }
        }
        _ => {}
    }
}

// ---------- drawing ----------
fn draw(out: &mut impl Write, app: &mut App) -> anyhow::Result<()> {
    let (w, h) = terminal::size().unwrap_or((80, 24));
    let (w, h) = (w as usize, h as usize);
    if w == 0 || h == 0 { return Ok(()); }
    let mut buf = Buffer::new(w, h);
    draw_header(&mut buf, app);
    if h >= 3 {
        let footer_y = h - 1;
        let mut main_area_h = footer_y - 1; // rows 1..footer_y
        let search_h = if app.search_open { 3usize } else { 0 };
        if search_h > 0 && main_area_h > search_h + 1 {
            main_area_h -= search_h;
        }
        let side = if app.help_open {
            Some(SideKind::Help)
        } else if !app.marked.is_empty() {
            Some(SideKind::Marked)
        } else {
            None
        };
        if let Some(kind) = side {
            let main_w = w / 2;
            draw_main_pane(&mut buf, app, 0, 1, main_w, main_area_h);
            draw_side_pane(&mut buf, app, main_w, 1, w - main_w, main_area_h, kind);
        } else {
            draw_main_pane(&mut buf, app, 0, 1, w, main_area_h);
        }
        if search_h > 0 {
            draw_search_pane(&mut buf, app, 0, 1 + main_area_h, w, search_h);
        }
        draw_footer(&mut buf, app, footer_y);
    }
    render_buffer(&buf, out)
}

#[derive(Clone, Copy, PartialEq)]
enum SideKind { Help, Marked }

fn header_bg(app: &App) -> u8 {
    if app.focus == Focus::Marked {
        9
    } else if !app.marked.is_empty() {
        3
    } else {
        15
    }
}

fn draw_header(buf: &mut Buffer, app: &App) {
    let bg = header_bg(app);
    let base = Style::plain().fg(0).bg(bg);
    buf.fill(0, 0, buf.w, Style::plain().bg(bg));
    let mut x = 0usize;
    let spans: Vec<(&str, Style)> = vec![
        (" D", base.bold()),
        ("isk ", base),
        ("U", base.bold()),
        ("sage ", base),
        ("A", base.bold()),
        ("nalyzer v2.32.2    ", base),
        ("(press ", base.underline()),
        ("?", base.bold().underline()),
        (" for help)", base.underline()),
    ];
    for (text, style) in spans {
        buf.set(x, 0, text, style);
        x += unicode_width::UnicodeWidthStr::width(text);
    }
}

fn block_style(focused: bool) -> Style {
    if focused { Style::plain().bold() } else { Style::plain().fg(8) }
}

fn draw_block(
    buf: &mut Buffer,
    x: usize,
    y: usize,
    w: usize,
    h: usize,
    focused: bool,
    title_left: &str,
    title_right: Option<&str>,
    title_bottom: Option<&str>,
) {
    if w < 2 || h < 2 { return; }
    let style = block_style(focused);
    // Borders
    buf.set(x, y, "┌", style);
    buf.set(x + w - 1, y, "┐", style);
    buf.set(x, y + h - 1, "└", style);
    buf.set(x + w - 1, y + h - 1, "┘", style);
    buf.hline(x + 1, y, w - 2, style);
    buf.hline(x + 1, y + h - 1, w - 2, style);
    for row in 1..h - 1 {
        buf.set(x, y + row, "│", style);
        buf.set(x + w - 1, y + row, "│", style);
    }
    // Titles are drawn over the border.
    if !title_left.is_empty() {
        buf.set_limit(x + 1, y, title_left, style, x + w - 1);
    }
    if let Some(right) = title_right {
        let rw = unicode_width::UnicodeWidthStr::width(right);
        let left_w = unicode_width::UnicodeWidthStr::width(title_left);
        // Only draw the right title if it fits next to the left one (this
        // mirrors the tui Block behaviour in narrow panes).
        if left_w + rw <= w - 2 && rw + 1 < w {
            buf.set(x + w - 1 - rw, y, right, style);
        }
    }
    if let Some(bottom) = title_bottom {
        let bw = unicode_width::UnicodeWidthStr::width(bottom);
        if bw <= w - 2 {
            buf.set(x + w - 1 - bw, y + h - 1, bottom, style);
        } else {
            // Right-aligned truncation: keep the rightmost part.
            let text = truncate_right(bottom, w - 2);
            let tw = unicode_width::UnicodeWidthStr::width(text.as_str());
            buf.set(x + w - 1 - tw, y + h - 1, &text, style);
        }
    }
}

fn truncate_right(text: &str, max_width: usize) -> String {
    use unicode_width::UnicodeWidthStr;
    if UnicodeWidthStr::width(text) <= max_width { return text.to_string(); }
    let mut out = String::new();
    let mut w = 0;
    for ch in text.chars().rev() {
        let cw = UnicodeWidthChar::width(ch).unwrap_or(0);
        if w + cw > max_width { break; }
        out.push(ch);
        w += cw;
    }
    out.chars().rev().collect()
}

const NAV_HINT: &str = " . = o|.. = u ── ⇊ = Ctrl+d|↓ = j|⇈ = Ctrl+u|↑ = k ";

fn draw_main_pane(buf: &mut Buffer, app: &mut App, x: usize, y: usize, w: usize, h: usize) {
    if w < 4 || h < 3 { return; }
    let entries = app.current_entries();
    // Clamp offset/selection for this viewport.
    let viewport = h - 2;
    if entries.is_empty() {
        app.selection = 0;
        app.offset = 0;
    } else {
        if app.selection >= entries.len() { app.selection = entries.len() - 1; }
        if app.selection < app.offset { app.offset = app.selection; }
        if app.selection >= app.offset + viewport { app.offset = app.selection + 1 - viewport; }
        if app.offset > entries.len().saturating_sub(viewport) && entries.len() > viewport {
            app.offset = entries.len() - viewport;
        }
        if entries.len() <= viewport { app.offset = 0; }
    }

    let current_node = app.current;
    let (visible, total_count, total_size) = if app.search_open && !app.search_results.is_empty() {
        let size: u64 = entries.iter().map(|(id, _)| app.node(*id).size).sum();
        let count: u64 = entries.iter().map(|(id, _)| app.node(*id).subtree_count).sum();
        (entries.len(), count, size)
    } else {
        let count: u64 = app
            .node(current_node)
            .children
            .iter()
            .filter(|&&c| app.node(c).alive)
            .map(|&c| app.node(c).subtree_count)
            .sum();
        (entries.len(), count, app.node(current_node).size)
    };
    let title_left = format!(
        " {} ({} visible, {} total, {}) ",
        app.node(current_node).title,
        visible,
        total_count,
        format_size(total_size, app.format)
    );
    let focused = app.focus == Focus::Main;
    let bottom = if focused {
        Some(" mark-move = d | mark-toggle = space | toggle-all = a ")
    } else {
        None
    };
    draw_block(buf, x, y, w, h, focused, &title_left, Some(NAV_HINT), bottom);

    // Parent total for percentages.
    let parent_total = if app.search_open && !app.search_results.is_empty() {
        total_size
    } else {
        app.node(current_node).size
    };

    for row in 0..viewport {
        let idx = app.offset + row;
        let yy = y + 1 + row;
        if idx >= entries.len() { break; }
        let (node_id, display_name) = &entries[idx];
        let node = app.node(*node_id);
        let selected = idx == app.selection && app.focus == Focus::Main || (idx == app.selection && app.focus != Focus::Marked && app.focus != Focus::Help);
        // In the original the main selection stays highlighted even when a
        // side pane is focused.
        let selected = idx == app.selection;
        let is_marked = app.marked_set.contains(node_id);
        let mut col_x = x + 1;
        let inner_right = x + w - 1; // exclusive (border)
        let row_style_base = if selected { Style::plain().reversed() } else { Style::plain() };
        if selected {
            buf.fill(col_x, yy, inner_right - col_x, row_style_base);
        }
        // mtime column
        if app.show_mtime {
            let dt: chrono::DateTime<chrono::Local> = node.mtime.into();
            let text = format!(" {}", dt.format("%d/%m/%Y %H:%M:%S"));
            buf.set_limit(col_x, yy, &text, row_style_base, inner_right);
            col_x += unicode_width::UnicodeWidthStr::width(text.as_str());
            buf.set_limit(col_x, yy, " | ", row_style_base, inner_right);
            col_x += 3;
        }
        // size column (green)
        let size_text = format_size(node.size, app.format);
        let size_style = Style::plain().fg(2);
        let size_style = if selected { size_style.reversed() } else { size_style };
        buf.set_limit(col_x, yy, &size_text, size_style, inner_right);
        col_x += unicode_width::UnicodeWidthStr::width(size_text.as_str());
        buf.set_limit(col_x, yy, " | ", row_style_base, inner_right);
        col_x += 3;
        // gauge
        let fraction = if parent_total > 0 {
            node.size as f64 / parent_total as f64
        } else {
            0.0
        };
        let gauge = match app.gauge_mode {
            GaugeMode::Both => {
                format!("{:>6.1}%  {}", fraction * 100.0, bar_string(fraction, 10))
            }
            GaugeMode::PercentOnly => {
                format!("{:>6.1}%", fraction * 100.0)
            }
            GaugeMode::BarOnly => bar_string(fraction, 10),
            GaugeMode::LargeBar => bar_string(fraction, 20),
        };
        // Percent field in the original is 7 wide including %; our format
        // above produces "  60.0%" (7 incl. sign space from >6.1 + %).
        buf.set_limit(col_x, yy, &gauge, row_style_base, inner_right);
        col_x += unicode_width::UnicodeWidthStr::width(gauge.as_str());
        buf.set_limit(col_x, yy, " | ", row_style_base, inner_right);
        col_x += 3;
        // entry-count column
        if app.show_count {
            let count_text = if node.is_dir {
                format!("{:>4}", node.subtree_count)
            } else if node.subtree_count == 0 {
                format!("{:>4}", 0)
            } else {
                "    ".to_string()
            };
            buf.set_limit(col_x, yy, &count_text, row_style_base, inner_right);
            col_x += 4;
            buf.set_limit(col_x, yy, " | ", row_style_base, inner_right);
            col_x += 3;
        }
        // name column
        let name_available = inner_right.saturating_sub(col_x + 1);
        let prefix = if node.is_dir { "/" } else { " " };
        let name_style = if is_marked {
            Style::plain().fg(3)
        } else if node.is_dir {
            Style::plain().fg(6)
        } else {
            Style::plain()
        };
        let name_style = if selected { let mut s = name_style; s.reversed = true; s } else { name_style };
        buf.set_limit(col_x, yy, prefix, name_style, inner_right);
        let name_text = if display_name == &node.name {
            node.name.clone()
        } else {
            display_name.clone()
        };
        let truncated = truncate_middle(&name_text, name_available);
        buf.set_limit(col_x + 1, yy, &truncated, name_style, inner_right);
    }
    // Scrollbar on the right border.
    if !entries.is_empty() {
        let cells = scrollbar_cells(viewport, entries.len(), app.selection);
        let style = Style::plain().bold();
        for (i, is_thumb) in cells.iter().enumerate() {
            buf.set(x + w - 1, y + 1 + i, if *is_thumb { "█" } else { "║" }, style);
        }
    }
}

fn draw_side_pane(buf: &mut Buffer, app: &mut App, x: usize, y: usize, w: usize, h: usize, kind: SideKind) {
    match kind {
        SideKind::Help => draw_help_pane(buf, app, x, y, w, h),
        SideKind::Marked => draw_marked_pane(buf, app, x, y, w, h),
    }
}

fn draw_help_pane(buf: &mut Buffer, app: &mut App, x: usize, y: usize, w: usize, h: usize) {
    let focused = app.focus == Focus::Help;
    draw_block(buf, x, y, w, h, focused, "Help", Some(NAV_HINT), None);
    let text = include_str!("help_text.txt");
    let lines: Vec<&str> = text.lines().collect();
    let viewport = h.saturating_sub(2);
    let max_scroll = lines.len().saturating_sub(viewport);
    if app.help_scroll > max_scroll { app.help_scroll = max_scroll; }
    let headings = ["Pane control", "Navigation", "Display", "Open/Mark/Search", "Mark entries pane", "Application control"];
    for row in 0..viewport {
        let idx = app.help_scroll + row;
        if idx >= lines.len() { break; }
        let line = lines[idx];
        let yy = y + 1 + row;
        let trimmed = line.trim();
        if headings.contains(&trimmed) {
            buf.set_limit(x + 1, yy, " ", Style::plain(), x + w - 1);
            buf.set_limit(x + 2, yy, trimmed, Style::plain().bold().underline(), x + w - 1);
        } else if let Some(pos) = line.find(" => ") {
            // Key span (green) from char 1 through the key.
            buf.set_limit(x + 1, yy, &line[..pos + 1], Style::plain().fg(2), x + w - 1);
            // The above includes a leading normal space approximated as
            // green; visually identical for space characters except colour
            // of a blank cell, which is not observable in plain captures.
            buf.set_limit(x + 1 + unicode_width::UnicodeWidthStr::width(&line[..pos + 1]), yy, &line[pos + 1..], Style::plain(), x + w - 1);
        } else {
            buf.set_limit(x + 1, yy, line, Style::plain(), x + w - 1);
        }
    }
}

fn draw_marked_pane(buf: &mut Buffer, app: &mut App, x: usize, y: usize, w: usize, h: usize) {
    let focused = app.focus == Focus::Marked;
    let total_count: u64 = app.marked.iter().map(|&id| app.node(id).subtree_count).sum();
    let total_size: u64 = app.marked.iter().map(|&id| app.node(id).size).sum();
    let title = format!("Marked {} items ({}) ", total_count, format_size(total_size, app.format));
    let bottom = if focused {
        Some(" mark-toggle = space,d | remove-all = a")
    } else {
        None
    };
    // When the marked pane has been activated at least once, its bottom
    // title can remain; the simple model only shows it while focused.
    draw_block(buf, x, y, w, h, focused, &title, Some(NAV_HINT), bottom);
    let viewport = h.saturating_sub(2);
    // Prompt row when focused or when it has been activated via q.
    let prompt_rows = if focused || app.marked_prompt && app.focus == Focus::Main && false { 1 } else { 0 };
    let show_prompt = focused;
    // Clamp marked selection / offset.
    let list_viewport = viewport.saturating_sub(if show_prompt { 1 } else { 0 });
    if app.marked.is_empty() {
        app.marked_selection = 0;
        app.marked_offset = 0;
    } else {
        if app.marked_selection >= app.marked.len() { app.marked_selection = app.marked.len() - 1; }
        if app.marked_selection < app.marked_offset { app.marked_offset = app.marked_selection; }
        if list_viewport > 0 && app.marked_selection >= app.marked_offset + list_viewport {
            app.marked_offset = app.marked_selection + 1 - list_viewport;
        }
        if app.marked.len() <= list_viewport { app.marked_offset = 0; }
    }
    let mut row = 0usize;
    if show_prompt {
        let yy = y + 1;
        // " Ctrl + t  to trash or  Ctrl + r  to delete without prompt"
        let mut cx = x + 1;
        let seg = |buf: &mut Buffer, cx: &mut usize, yy: usize, text: &str, style: Style, limit: usize| {
            buf.set_limit(*cx, yy, text, style, limit);
            *cx += unicode_width::UnicodeWidthStr::width(text);
        };
        seg(buf, &mut cx, yy, " ", Style::plain(), x + w - 1);
        seg(buf, &mut cx, yy, "Ctrl + t ", Style::plain().fg(15).bg(0), x + w - 1);
        seg(buf, &mut cx, yy, " to trash or ", Style::plain().fg(0).bg(3), x + w - 1);
        let mut blink_style = Style::plain().fg(9).bg(0);
        blink_style.blink = true;
        seg(buf, &mut cx, yy, "Ctrl + r ", blink_style, x + w - 1);
        seg(buf, &mut cx, yy, " to delete without prompt", Style::plain().fg(0).bg(3), x + w - 1);
        row += 1;
    }
    let _ = prompt_rows;
    for i in 0..list_viewport {
        let idx = app.marked_offset + i;
        if idx >= app.marked.len() { break; }
        let yy = y + 1 + row + i;
        let id = app.marked[idx];
        let node = app.node(id);
        let selected = idx == app.marked_selection && focused;
        // When unfocused, the first marked entry is still shown reversed in
        // the original when the pane was just opened? It is not; keep plain.
        let base = if selected { Style::plain().reversed() } else { Style::plain() };
        if selected { buf.fill(x + 1, yy, w - 2, base); }
        let name_style = Style::plain().fg(3);
        let name_style = if selected { name_style.reversed() } else { name_style };
        let name_text = format!(" {}", node.name);
        buf.set_limit(x + 1, yy, &name_text, name_style, x + w - 1);
        let size_text = format_size(node.size, app.format);
        let size_with_space = format!("{} ", size_text);
        let sw = unicode_width::UnicodeWidthStr::width(size_with_space.as_str());
        let size_style = Style::plain().fg(2);
        let size_style = if selected { size_style.reversed() } else { size_style };
        if x + w - 1 > sw {
            buf.set_limit(x + w - 1 - sw, yy, &size_with_space, size_style, x + w - 1);
        }
    }
    if !app.marked.is_empty() {
        let cells = scrollbar_cells(list_viewport.max(1), app.marked.len(), app.marked_selection);
        let style = if focused { Style::plain().bold() } else { Style::plain().fg(8) };
        // Scrollbar is drawn on the border with block style boldness in the
        // original for the focused pane; unfocused uses grey.
        let style = Style::plain().bold();
        let _ = style;
        for (i, is_thumb) in cells.iter().enumerate() {
            if row + i >= viewport { break; }
            buf.set(x + w - 1, y + 1 + row + i, if *is_thumb { "█" } else { "║" }, Style::plain().bold());
        }
    }
}

fn draw_search_pane(buf: &mut Buffer, app: &App, x: usize, y: usize, w: usize, h: usize) {
    let focused = app.focus == Focus::Search;
    let title = if app.search_case_sensitive {
        "Git-Glob (case-sensitive)"
    } else {
        "Git-Glob (case-insensitive)"
    };
    draw_block(
        buf,
        x,
        y,
        w,
        h,
        focused,
        title,
        Some(" search = enter | case = ^f | cancel = esc "),
        None,
    );
    if h > 2 {
        let text = format!(" {}", app.search_text);
        buf.set_limit(x + 1, y + 1, &text, Style::plain(), x + w - 1);
    }
}

fn draw_footer(buf: &mut Buffer, app: &App, y: usize) {
    let style = Style::plain().reversed();
    buf.fill(0, y, buf.w, style);
    let mut text = format!(
        "Sort mode: {}  Total disk usage: {}  Processed {} entries in {:.2}s",
        app.sort_mode.label(),
        format_size(app.node(app.graph.top).size, app.format),
        app.graph.processed_entries,
        app.graph.processed_seconds
    );
    if let Some(msg) = &app.status_message {
        text.push_str("  ");
        text.push_str(msg);
    }
    buf.set_limit(0, y, &text, style, buf.w);
}

