/// Like the internal effective-size calculation, but also reports whether
/// the entry was suppressed as a hard-link duplicate.
pub fn effective_size_flag(
    state: &mut TraversalState,
    metadata: &fs::Metadata,
    apparent_size: bool,
    count_hard_links: bool,
) -> (u64, bool) {
    let size = entry_size(metadata, apparent_size);
    if count_hard_links {
        return (size, false);
    }
    if metadata.nlink() > 1 {
        let key = (metadata.dev(), metadata.ino());
        if !state.seen_inodes.insert(key) {
            return (0, true);
        }
    }
    (size, false)
}
