{"command":"cat > /tmp/cellparse.py << 'PY'
import re
def parse_capture(text):
    lines=text.splitlines()
    grid=[]
    for line in lines:
        cells=[] # list of (char, attrs tuple string)
        attrs=set()
        i=0
        # tmux -e sequences are CSI ... m
        tokens=re.split(r'(\x1b\[[0-9;]*m)', line)
        for tok in tokens:
            if tok.startswith('\x1b['):
                # parse SGR
                nums=tok[2:-1].split(';') if tok[2:-1] else ['0']
                j=0
                while j < len(nums):
                    n=nums[j]
                    if n=='' : n='0'
                    try: v=int(n)
                    except: j+=1; continue
                    if v==0: attrs=set()
                    elif v==1: attrs.add('bold')
                    elif v==4: attrs.add('underline')
                    elif v==5: attrs.add('blink')
                    elif v==7: attrs.add('rev')
                    elif v==22: attrs.discard('bold')
                    elif v==24: attrs.discard('underline')
                    elif v==27: attrs.discard('rev')
                    elif v==39: attrs.discard('fg')
                    elif v==49: attrs.discard('bg')
                    elif v in (38,48):
                        # 38;5;n
                        try:
                            val=nums[j+2]
                            attrs.discard('fg' if v==38 else 'bg')
                            attrs.add(('fg' if v==38 else 'bg')+val)
                            j+=2
                        except: pass
                    j+=1
            else:
                for ch in tok:
                    cells.append((ch,tuple(sorted(str(a) for a in attrs))))
        grid.append(cells)
    return grid

def compare_cells(label, a_text,b_text):
    a=parse_capture(a_text); b=parse_capture(b_text)
    diffs=0
    for y in range(max(len(a),len(b))):
        ra=a[y] if y<len(a) else []; rb=b[y] if y<len(b) else []
        for x in range(max(len(ra),len(rb))):
            ca=ra[x] if x<len(ra) else ('<none>',())
            cb=rb[x] if x<len(rb) else ('<none>',())
            if ca!=cb:
                diffs+=1
                if diffs<30: print(label, "cell",y,x,"orig",ca,"ours",cb)
    print(label,"cell diffs",diffs)
    return diffs
