            if app.focus == Focus::Main { st.bold = true; }
            st
        } else {
            Style::plain()
        };""")
s=s.replace("""        let size_style = if selected {
            let mut st = size_style;
            st.bold = true;
            st.reversed = true;
            st
        } else {
            size_style
        };""", """        let size_style = if selected {
            let mut st = size_style;
            if app.focus == Focus::Main { st.bold = true; }
            st.reversed = true;
            st
        } else {
            size_style
        };""")
s=s.replace("""        let name_style = if selected {
            let mut s = name_style;
            s.bold = true;
            s.reversed = true;
            s
        } else {
            name_style
        };""", """        let name_style = if selected {
            let mut s = name_style;
            if app.focus == Focus::Main { s.bold = true; }
            s.reversed = true;
            s
        } else {
            name_style
        };""")
# Green first column logic: set mtime and size styles conditionally.
# Replace mtime draw block style: need introduce vars before columns.
s=s.replace("""        // mtime column
        if app.show_mtime {
            let dt: chrono::DateTime<chrono::Local> = node.mtime.into();
            let text = format!(" {}", dt.format("%d/%m/%Y %H:%M:%S"));
            buf.set_limit(col_x, yy, &text, row_style_base, inner_right);""", """        // mtime column (green when it is the first column)
        if app.show_mtime {
            let dt: chrono::DateTime<chrono::Local> = node.mtime.into();
            let text = format!(" {}", dt.format("%d/%m/%Y %H:%M:%S"));
            let mtime_style = if selected {
                let mut st = Style::plain().fg(2);
                if app.focus == Focus::Main { st.bold = true; }
                st.reversed = true;
                st
            } else {
                Style::plain().fg(2)
            };
            buf.set_limit(col_x, yy, &text, mtime_style, inner_right);""")
# Size style: green only if mtime not shown
s=s.replace("""        // size column (green)
        let size_text = format_size(node.size, app.format);
        let size_style = Style::plain().fg(2);""", """        // size column (green unless mtime is the first/green column)
        let size_text = format_size(node.size, app.format);
        let size_style = if app.show_mtime {
            row_style_base
        } else {
            Style::plain().fg(2)
        };""")
# The later size_style selected transform assumes fg; it sets bold/rev on whatever base - fine.
# Search results name not cyan
s=s.replace("""        let name_style = if is_marked {
            Style::plain().fg(3)
        } else if node.is_dir {
            Style::plain().fg(6)
        } else {
            Style::plain()
        };""", """        let name_style = if is_marked {
            Style::plain().fg(3)
        } else if in_search_results {
            Style::plain()
        } else if node.is_dir {
            Style::plain().fg(6)
        } else {
            Style::plain()
        };""")
# Need move in_search_results definition before name_style: it is currently defined at prefix line after name_style? Check order: prefix def is after name_style in code (in_search defined at prefix). Move by defining early duplicate.
s=s.replace("""        // name column
        let name_available = inner_right.saturating_sub(col_x + 1);""", """        // name column
        let in_search_results = app.search_open && !app.search_results.is_empty();
        let name_available = inner_right.saturating_sub(col_x + 1);""")
# Remove duplicate later def (it redefines same name - allowed shadowing but keep)
# Marked size draw: only draw size_text green, position accounting two trailing cells
s=s.replace("""        buf.set_limit(x + 1, yy, &name_text, name_style, x + w - 1);
        let size_text = format_size(node.size, app.format);
        let size_with_space = format!("{}  ", size_text);
        let sw = unicode_width::UnicodeWidthStr::width(size_with_space.as_str());
        let size_style = Style::plain().fg(2);""", """        buf.set_limit(x + 1, yy, &name_text, name_style, x + w - 1);
        let size_text = format_size(node.size, app.format);
        let size_with_space = format!("{}  ", size_text);
        let sw = unicode_width::UnicodeWidthStr::width(size_with_space.as_str());
        let size_style = Style::plain().fg(2);""")
# That block appears in main? Actually marked block has different preceding lines, replacements may affect marked only if unique. We'll adjust marked draw below.
open(p,"w").write(s)
