seq=[0,0,1,1,1,2,2,2,3,3,4,4,4,5,5,5]
best=[]
import math
for thumb in range(1,17):
 for b in range(-35,36):
  for a in range(-3,4):
   for mode in ['floor','round','ceil']:
    err=0
    for sel,s in enumerate(seq):
