new_fn = '''pub fn walk_aggregate(
    path: &Path,
    is_root: bool,
    root_device: Option<u64>,
    opts: &WalkOptions,
    state: &mut TraversalState,
    errors: &mut u64,
) -> u64 {
    // Canonicalise once at the root; descendants' canonical paths are
    // derived by joining file names (we never descend through symlinks,
    // so this is equivalent to canonicalising every directory, without
    // the cubic cost on deep trees).
    let canon = path
        .canonicalize()
        .unwrap_or_else(|_| path.to_path_buf());
    walk_inner(path, &canon, is_root, root_device, opts, state, errors)
}

fn walk_inner(
    path: &Path,
    canon: &Path,
    is_root: bool,
    root_device: Option<u64>,
    opts: &WalkOptions,
    state: &mut TraversalState,
    errors: &mut u64,
) -> u64 {
    let (mut info, followed_dev) = if is_root {
        match info_explicit_root(path) {
            Some((info, followed)) => {
                let dev = followed.dev();
                (info, Some(dev))
            }
            None => {
                *errors += 1;
                return 0;
            }
        }
    } else {
        match info_nested(path) {
            Some(info) => (info, None),
            None => {
                *errors += 1;
                return 0;
            }
        }
    };
    let root_device = if is_root {
        followed_dev
    } else {
        root_device
    };
    let size = state.effective_size(&info.metadata, opts.apparent_size, opts.count_hard_links);
    info.size = size;
    state.statistics.add(size);
    let mut total = size;

    let descend = if is_root { info.is_dir_follow } else { info.is_real_dir };
    if !descend {
        return total;
    }
    // Ignore check: applies to nested dirs and to explicit roots alike.
    // (The single-input directory case never reaches here with the input
    // itself, because it is expanded before traversal.)
    if state.ignore_set.contains(canon) {
        return total;
    }
    if opts.stay_on_filesystem && !is_root {
        if let Some(rd) = root_device {
            if info.metadata.dev() != rd {
                return total;
            }
        }
    }
    // Collect entries first so the directory handle is closed before
    // recursing (otherwise deep trees exhaust the file-descriptor limit).
    let child_paths: Vec<PathBuf> = match fs::read_dir(path) {
        Ok(read_dir) => read_dir
            .filter_map(|e| e.ok().map(|e| e.path()))
            .collect(),
        Err(_) => Vec::new(),
    };
    for child in &child_paths {
        let child_canon = match child.file_name() {
            Some(name) => canon.join(name),
            None => child.clone(),
        };
        total += walk_inner(child, &child_canon, false, root_device, opts, state, errors);
    }
    total
}

